window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q09"]=window.__LIBQ["the-gioi-hoan-my"]["q09"]||{};window.__LIBQ["the-gioi-hoan-my"]["q09"]["cotTruyen"]=[{"chuong":801,"tieuDe":"Khu Không Người","tomTat":"Chuông cổ vang khắp ba ngàn châu, mở đầu cuộc truyền tống năm mươi triệu Tôn giả vượt ải vào ba ngàn khu vực dự tuyển trong khu vực không người. Thạch Hạo bị những người đồng hành ở Tội châu tránh xa vì chiến tích giết Thần, rồi biết rằng chỉ vài triệu người có thể tiến vào Tiên cổ và Phá vực phù là phương tiện rút lui khi gặp nguy hiểm. Hoa Tiên đạo xuất hiện, mang theo tiên quang và điềm lành tạm áp chế các sinh vật cực hung, nhưng những hiểm họa từng giết Giáo chủ vẫn khiến nơi này vô cùng nguy hiểm. Các Giáo chủ xác nhận lần nở thứ ba nghìn sẽ là lần viên mãn cuối cùng, tạo ra ba ngàn cánh hoa đại đạo để mở đường và quan sát Tiên cổ. Bên ngoài khu vực, chiến xa Thiên quốc, đồng điện Tiên điện cùng người của nhiều đạo thống lớn lần lượt hội tụ, trong khi Tần Di Ninh lo lắng cho Thạch Hạo và Thạch Tử Lăng trở về tiễn Tần Hạo. Người Tần tộc đặt nhiều kỳ vọng vào song cốt Chí tôn và bảo dịch bất tử của Tần Hạo. Trong thời gian chờ đợi, một người tìm thấy vật chất bất tử nhưng bị truy sát đến mức phải dùng Phá vực phù rời đi. Sang ngày thứ ba, ráng màu và tiên quang dâng ngập chân trời, báo hiệu Hoa Tiên đạo sắp nở và con đường vào Tiên cổ sắp mở."},{"chuong":802,"tieuDe":"Một Góc Tương Lai","tomTat":"Hoa Tiên đạo bắt đầu nở, khiến đại đạo cộng hưởng, tiên khí lan khắp sơn hà và gột rửa thương thế, mệt mỏi của đoàn Tôn giả. Một sinh linh khổng lồ phủ lông đỏ xuất hiện, dùng khí tức tà dị áp chế mọi người rồi định nuốt hoa, nhưng bị ánh sáng từ hoa đánh cho hộc máu đen và phải rút lui. Ba ngàn cánh hoa lần lượt hé mở, phát ra mưa ánh sáng mang khí tức Tiên đạo, giúp năm mươi triệu Tôn giả tăng thêm ít nhất một trăm năm tuổi thọ. Các Giáo chủ sau đó tiết lộ tuổi thọ dài của sinh linh thượng giới phụ thuộc vào lượng vật chất bất tử mỏng manh thẩm thấu từ một nơi khác, và nếu nguồn này bị đoạn tuyệt thì ngay cả cường giả mạnh nhất cũng chỉ có thể sống khoảng một đến hai vạn năm. Cô gái Đế tộc liên hệ thời điểm ba ngàn cánh hoa nở hết với giai đoạn cuối của kỷ nguyên, trong khi cổ thụ gần phong hóa cảnh báo đại chiến sẽ lan từ biên hoang và phá vỡ ba ngàn châu. Dù có người nhấn mạnh tương lai vẫn tồn tại biến số, một sinh vật đáng sợ bất ngờ xuất hiện cuối chương, khiến tộc trưởng đại tộc không dám gọi tên và buộc Tiệt Thiên Giáo chủ dùng bản nguyên thiên địa kiểm chứng khí thế của nó."},{"chuong":803,"tieuDe":"Hoa Tiên Đạo Nở","tomTat":"Một sinh vật hình rồng khổng lồ xuất hiện giữa khu không người và nhiều lần xung kích Hoa Tiên đạo, nhưng bị sức mạnh đại đạo đánh trọng thương; khi đôi cánh của nó lộ ra, Tiệt Thiên Giáo chủ nhận diện đây là Ứng long. Máu của Ứng long rơi xuống khiến các sơ đại và cường giả vượt giới bích tới tranh đoạt, còn Thiên yêu Cát Tiềm từ bỏ long huyết sau khi cảm nhận được nguy hiểm. Cát Tiềm tìm cách thu phục Thạch Hạo, nhưng hai bên chưa kịp giao chiến thì Ứng long dùng long uy giam cầm khu vực và thả xuống một khối chất thải lớn như núi. Thạch Hạo dùng chiến kích Hư không cắt lìa không gian để thoát thân, trong khi Cát Tiềm cùng nhiều Tôn giả bị chôn lấp; các Giáo chủ nghi Ứng long cố ý lưu khí tức để sau này xác định tọa độ Tiên cổ. Khi cánh hoa cuối cùng nở rộ, ba ngàn đại lộ kim quang trải tới toàn bộ khu vực tuyển chọn và Cát Tiềm bất ngờ trở thành người đầu tiên tiến vào cánh cửa trên hoa. Sau đó, năm trăm vạn tu sĩ được kim quang dẫn tới Hoa Tiên đạo, trong đó có Lục Quang vương, truyền nhân Tiên điện, Cô Kiếm Vân và Quân Đạo. Sự kiện này đánh dấu cuộc tranh bá thiên tài ba ngàn châu chính thức bắt đầu, trong lúc Ứng long cùng nhiều sinh vật đáng sợ vẫn đứng ngoài khu không người theo dõi."},{"chuong":804,"tieuDe":"Tiên Cổ","tomTat":"Kèn lệnh thượng giới vang lên khi Hoa Tiên đạo nở đủ ba ngàn cánh, báo hiệu lần mở Tiên Cổ cuối cùng trong kỷ nguyên. Gần năm trăm vạn Tôn giả tiến qua các Tiên môn, còn hơn mười vạn người vừa nhen nhóm Thần Hỏa bị đại đạo quét ra ngoài. Thạch Hạo không thể cưỡng ép tiếp cận cánh hoa thứ 3000 nên vào bằng một cửa khác, sau đó nghiên cứu bậc đá và liên tiếp đánh xuyên giới bích để tới đúng con đường cuối cùng. Các Giáo chủ hợp lực phản chiếu cảnh tượng trong Tiên Cổ lên ba ngàn bia ngọc, qua đó theo dõi những cuộc tranh phong gần cuối đường đá. Ninh Xuyên giao chiến với Lý Phồn Minh, truyền nhân Tiên điện đối đầu chàng trai mang một góc Khay Luân hồi, còn Tam thạch Thiên quân tái hiện và một mình áp chế năm chí tôn trẻ tuổi. Thập Quan vương cùng một quái thai cổ đại khác bình tĩnh tiến lên mà chưa gặp đối thủ. Bên ngoài, các Giáo chủ bắt đầu tìm Hoang và người đời sau tội huyết, trong khi người bên cạnh Tần Trường Sinh xin dò xét thiếu niên hạ giới nhưng không nhận được thái độ rõ ràng từ ông."},{"chuong":805,"tieuDe":"Thân Phận Rõ Ràng","tomTat":"Các đại giáo từng chịu tổn thất tại Linh giới dùng cánh hoa Tiên đạo và bia đá để truy tìm thiếu niên mang danh Tội, trong khi Thạch Hạo đang đi ngang qua các con đường đá của Tiên cổ để đo đạc và cảm ngộ. Tào Vũ Sinh dùng kiếm khí từ Sát trận thứ ba quét sạch những người vây đánh mình, còn Trùng đồng giả của thư viện Thiên Vẫn chỉ dùng ánh mắt đã tiêu diệt hơn mười đối thủ. Khi Chủ Minh thổ khắc chữ Hoang, bia đá hiện đúng thiếu niên từng xuất hiện dưới chữ Tội, khiến hai thân phận được công khai xác nhận là một. Tần Trường Sinh sau đó khắc tên Tần Hạo, để quần tu chứng kiến uy lực Song cốt Chí tôn và biết một khối Chí Tôn cốt của thiếu niên đến từ huynh trưởng. Tần Di Ninh vẫn thương tiếc Thạch Hạo, còn Thạch Tử Lăng im lặng quan sát phản ứng của Tiên điện. Cuối cùng, người trong cung điện đồng của Tiên điện khắc tên Thạch Hạo, khiến cùng một thiếu niên xuất hiện lần thứ ba và hoàn tất việc hợp nhất công khai ba danh xưng Tội, Hoang và Thạch Hạo."},{"chuong":806,"tieuDe":"Từ Nay Ta Chính Là Ta","tomTat":"Ngoại giới chấn động khi xác nhận Tội, Hoang, Hạo Thiên và Thạch Hạo đều là một người, đồng thời nhận ra thiếu niên từng được cho là đã chết ở hạ giới vẫn còn sống. Thạch Hạo cảm nhận mình đang bị quan sát nên chủ động giải trừ hóa trang, khôi phục diện mạo thật và thề từ nay sẽ làm chính mình. Tần Di Ninh cùng Thạch Tử Lăng vui mừng nhận lại con trưởng nhưng cũng đau lòng, hổ thẹn khi nhớ đến những khổ nạn và việc hắn tự chém Chí Tôn cốt trao cho Tần Hạo. Minh chủ, Chủ Ma Quỳ viên, Chủ Thiên quốc và người của Tiên điện lần lượt bộc lộ địch ý, trong đó Chủ Thiên quốc tuyên bố sẽ lấy máu hắn hiến tế Tích Huyết Ma kiếm. Thạch Hạo đáp trả bằng cách công khai khiêu chiến Thiên quốc, Minh thổ, Tiên điện, Thiên Nhân tộc cùng các đạo thống trông coi Tội châu, đồng thời đe dọa thanh toán môn đồ và truyền nhân của họ trong Tiên cổ. Không còn cần che giấu thân phận, hắn tuyên bố có thể triển khai toàn bộ bảo thuật. Đôi cánh Côn Bằng khổng lồ hiện ra sau lưng Thạch Hạo và chỉ một lần vỗ đã đánh nổ những sinh linh âm thầm tập kích, báo hiệu một trận sóng gió lớn sắp nổi lên trong Tiên cổ."},{"chuong":807,"tieuDe":"Cổ Giới Đầy Màu Sắc","tomTat":"Sau khi Thạch Hạo áp đảo nhiều Tôn giả trên cổ lộ, nhóm người đầu tiên vượt khỏi ba ngàn con đường đá và tiến vào Tiên cổ ngay ngày thứ chín, sớm hơn các đời trước. Qua những bia đá quan sát, người ngoài nhận ra Tiên cổ gồm vô số địa vực nhiều màu rộng như các tiểu thiên thế giới, có thể liên thông với nhau và ẩn chứa cả thánh địa lẫn hiểm địa. Truyền nhân Đại Phần Thiên công giao chiến với truyền nhân Tiên điện, trong khi Trường Cung Diễn, Cô Kiếm Vân và các nhân kiệt cổ đại khác cũng tranh đoạt cổ địa. Những người hiểu rõ Tiên cổ nhanh chóng tách ra tìm tiên trì máu Phượng hoàng, cổ động Kỳ lân và ngọn núi ngộ đạo của Thập Hung để hoàn mỹ nhen nhóm Thần hỏa. Người đến sau phải tự chọn địa vực và thăm dò, còn Thạch Hạo quan sát một cổ địa có thành trì đen cùng sa mạc có dấu hiệu của suối sinh mệnh nhưng vẫn chưa quyết định tiến vào. Hắn muốn tiếp tục tham khảo cổ lộ nhằm hoàn thiện con đường Thần hỏa của mình. Đúng lúc đó, truyền nhân Tiên điện mặc giáp trụ Tiên vũ xuyên ngược nhiều giới bích trở lại cửa ngõ, nhận ra Thạch Hạo và lập tức lao tới. Thạch Hạo lấy chiến kích Hư không, chủ động chém ra đòn mở màn cho cuộc tái chiến."},{"chuong":808,"tieuDe":"Tiên Cổ","tomTat":"Kèn lệnh thượng giới vang khắp ba ngàn châu khi cánh thứ ba nghìn của Hoa Tiên đạo lần đầu nở, báo hiệu lần mở Tiên Cổ cuối cùng trong kỷ nguyên. Mưa đạo khiến nhiều tu sĩ đốn ngộ, nhưng hơn mười vạn người đột phá và nhen nhóm Thần Hỏa không đúng lúc bị đại đạo quét khỏi cánh hoa. Thạch Hạo nhiều lần thất bại khi muốn trực tiếp tới cánh hoa mới nở, cuối cùng phải bước qua một Tiên môn khác và trở thành người tiến vào sau cùng. Trên ba ngàn con đường đá xanh, hắn nghiên cứu bậc đá rồi liên tục đánh xuyên giới bích để chuyển tới con đường tương ứng với cánh hoa thứ ba nghìn. Các Giáo chủ hợp lực chiếu cảnh tượng trong Tiên Cổ lên ba ngàn bia ngọc và đến ngày thứ chín phát hiện nhiều thiên kiêu đã gần tới thế giới sặc sỡ cuối đường. Ninh Xuyên giao chiến với Lý Phồn Minh, truyền nhân Tiên điện đối đầu chàng trai cầm một góc Khay Luân Hồi, còn Tam thạch Thiên quân tái hiện và một mình áp chế năm chí tôn trẻ tuổi. Ngoại giới sau đó chuẩn bị tìm Hoang cùng người đời sau tội huyết, trong khi người bên cạnh Tần Trường Sinh báo tin về thiếu niên hạ giới nhưng không nhận được phản ứng rõ ràng từ ông."},{"chuong":809,"tieuDe":"Thân Phận Rõ Ràng","tomTat":"Các thế lực thù địch dùng cánh hoa Tiên đạo và bia đá để truy tìm hậu duệ Tội huyết, qua đó quan sát được Thạch Hạo đang đi ngang giữa những con đường trong Tiên cổ để thể ngộ. Một bia đá khác chiếu cảnh Tào Vũ Sinh vận dụng Sát trận thứ ba khắc trong cơ thể, hóa ra kiếm khí giết cao thủ đứng đầu Địa Ma tộc cùng nhiều đối thủ. Khi Chủ Minh thổ khắc tên Hoang, bia đá vẫn hiện đúng thiếu niên từng được chữ Tội gọi ra, khiến quần hùng xác nhận Hoang và hậu duệ Tội huyết là một người. Trùng đồng giả của thư viện Thiên Vẫn sau đó hiện lên với chiến tích tiêu diệt hơn mười cao thủ, đồng thời quá khứ từng thua Thạch Hạo tại hạ giới được nhắc lại. Tần Trường Sinh khắc tên Tần Hạo, để mọi người chứng kiến sức mạnh tiên quang từ hai khối Chí Tôn cốt của hắn và bàn luận về nguồn gốc khối cốt do Thạch Hạo để lại. Cuối cùng, người trong cung điện đồng của Tiên điện khắc thẳng tên Thạch Hạo, khiến bia đá lần thứ ba hiện cùng một thiếu niên và công khai xác nhận Thạch Hạo, Hoang cùng hậu duệ Tội huyết chính là một người."},{"chuong":810,"tieuDe":"Từ Nay Ta Chính Là Ta","tomTat":"Hình ảnh Thạch Hạo lần thứ ba xuất hiện trên bia đá khiến quần hùng ngoài Tiên cổ nhận ra Tội, Hoang và Thạch Hạo vốn là cùng một người. Biết ngoại giới đang quan sát, hắn khôi phục dung mạo thật, công khai thêm danh xưng Hạo Thiên và tuyên bố từ nay sẽ chỉ sống dưới thân phận của chính mình. Tần Di Ninh cùng Thạch Tử Lăng vui mừng đến rơi lệ khi xác nhận con trưởng còn sống, nhưng cũng day dứt vì những đau khổ hắn từng một mình gánh chịu. Trong khi đó, Minh thổ, Thiên quốc, Tiên điện và Ma Quỳ viên nổi giận khi nhớ lại việc Thạch Hạo từng phá hỏng kế hoạch đưa thần xuống hạ giới. Thạch Hạo công khai khiêu chiến các đại giáo, tố Thiên Nhân tộc muốn độc chiếm Bảo thuật Côn Bằng và lên án những đạo thống trông giữ Tội châu đã vu tội hậu nhân biên hoang. Cuối cùng, hắn tuyên bố không còn áp chế thực lực, diễn hóa cánh Côn Bằng và chỉ một lần vỗ cánh đã giết sạch những sinh linh âm thầm tập kích phía sau."},{"chuong":811,"tieuDe":"Cổ Giới Đầy Màu Sắc","tomTat":"Những quái thai cổ đại đầu tiên vượt qua ba ngàn cổ lộ vào ngày thứ chín, sớm hơn tiền lệ một ngày, khiến áp lực trên các con đường giảm xuống và giúp những người phía sau tiến nhanh hơn. Qua các bia đá quan sát, ngoại giới nhận ra Tiên cổ gồm vô số địa vực nhiều màu rộng lớn như những tiểu thiên thế giới, có thể nối thông nhưng sở hữu hoàn cảnh, cơ duyên và hiểm họa khác nhau. Truyền nhân Đại Phần Thiên Công chọn truyền nhân Tiên điện làm mục tiêu đầu tiên trong kế hoạch săn giết cường giả, sử dụng ngọn lửa đen giao chiến dữ dội với đối phương. Trường Cung Diễn, Cô Kiếm Vân và những quái thai cổ đại khác cũng tranh đoạt cổ địa rồi nhanh chóng tách ra, hướng tới các bảo địa đã chọn để chuẩn bị nhen nhóm Thần hỏa hoàn mỹ. Thạch Hạo tiến vào Tiên cổ trước phần lớn tu sĩ nhưng chưa vội chọn địa giới, bởi hắn muốn nghiên cứu ba ngàn bậc thang nhằm tham khảo cho con đường viên mãn Thần hỏa. Trong lúc hắn quan sát các địa giới có thành trì, chủng tộc bản địa và sa mạc chứa hơi nước thánh khiết, truyền nhân Tiên điện mặc giáp trụ Tiên vũ, cầm đại kích xuyên qua nhiều giới bích trở lại. Hai người phát hiện nhau và lập tức khai chiến, Thạch Hạo lấy chiến kích Hư không chủ động chém về phía đối thủ."},{"chuong":812,"tieuDe":"Con Đường Khác Nhau","tomTat":"Thạch Hạo dùng chiến kích Hư không đối đầu ngang ngửa truyền nhân Tiên điện đã dung hợp chủ–thứ thân và bước đầu mở Võ đạo Thiên nhãn. Truyền nhân Tiên điện thua thế, chạy vào tiểu thiên thế giới để mượn giao long Thiên Thần đang truy sát mình quay sang giết Thạch Hạo, nhưng Thạch Hạo kịp cắt hư không thoát thân. Giao long nuốt hơn mười Tôn giả rồi bị xích sắt phù văn kéo trở lại cọc đá cạnh hang rồng, để lộ bảo địa thần thánh chưa ai khai phá. Trong khi các sơ đại và quái thai cổ đại vội tìm bảo địa để lột xác tiến vào Thần Hỏa cảnh, Thạch Hạo quay lại ba ngàn con đường đá, quyết lấy thiên địa làm lò, vạn đạo làm lửa để thiêu luyện thân thể và nguyên thần, xây dựng chân ngã riêng dù biết con đường này gần như toàn bộ người cổ đại đều thất bại. Sau nhiều tháng, các Tôn giả và sơ đại lần lượt thành thần. Một quái thai cổ đại lấy tiên huyết làm lửa gieo tiên chủng, Thập Quan vương trồng cây nhỏ bí ẩn vào cơ thể, và nhiều quái thai khác cũng dùng những trân vật vạn cổ khó gặp để hoàn thành lần lột xác vượt khỏi ý nghĩa thông thường."},{"chuong":813,"tieuDe":"Đua Nhau Thành Thần","tomTat":"Hơn năm tháng trôi qua, Thạch Hạo vẫn luân chuyển giữa ba ngàn con đường đá Tiên cổ để tìm hiểu đại đạo, mặc cho ngoại giới cho rằng hắn đã bỏ lỡ thời cơ thành thần. Trong khi đó, hơn ba triệu Tôn giả đã hoàn tất lột xác; một quái thai cổ đại còn dung hợp chất lỏng màu đen để thử phương thức thành thần không dựa vào việc nhen nhóm bản thân. Ninh Xuyên tiếp tục án binh bất động bên một hộp báu bị phong ấn, khiến người ngoài vừa tò mò về vật bên trong vừa lo hắn sẽ trở thành mục tiêu của những người xuất quan trước. Cuộc săn giết nhanh chóng bắt đầu khi một tán tu thành thần sát hại sơ đại đang bế quan, còn sinh linh mặc giáp tại thành đen và bầy côn trùng trong một cổ giới khác cũng giết nhiều người ngoại lai. Sơ đại Yêu Long đạo môn thành thần bằng cổ hỏa, chí tôn trẻ tuổi La Phù chân cốc xuất quan, đồng thời hậu đại mạnh mẽ của Minh thổ, Thiên quốc và Thú hải lần lượt thăng cấp, làm hiểm họa nhằm vào Thạch Hạo tăng cao. Cuối chương, Thạch Hạo ngồi xếp bằng, toàn thân phát sáng và được những nhóm ký hiệu lớn bao quanh, nhưng thân thể cũng bị đốt thủng nhiều chỗ. Khi đám đông chế giễu hắn tự thiêu, lão đạo chủ Yêu Long đạo môn và động chủ Hỏa Vân động lại im lặng quan sát với vẻ nghiêm túc."},{"chuong":814,"tieuDe":"Lô Hỏa Thuần Thanh","tomTat":"Thạch Hạo thử dẫn hơn mười loại đạo tắc vào thân nhưng nhanh chóng nhận ra cách làm này chỉ thiêu hủy huyết nhục, xương cốt và tinh hồn của chính mình. Hắn sửa lại phương pháp bằng cách cô đọng hư không thành lò càn khôn, dùng các đại đạo làm lửa nung luyện thân thể, nguyên thần và chân ngã thay vì mô phỏng cổ pháp. Sau nhiều tháng, hắn dung hợp một trăm lẻ tám luồng đạo hỏa, khiến ngọn lửa chuyển xanh và đạt bước đầu của trạng thái lô hỏa thuần thanh, đồng thời đặt mục tiêu cuối cùng là dẫn đủ ba ngàn ánh lửa đại đạo. Quá trình này khiến hắn cháy đen, gần cạn sinh cơ và phải nằm bất động năm ngày mới tỉnh lại. Để bổ sung tinh khí và thần lực, Thạch Hạo tiến vào một tiểu thiên thế giới lộng lẫy rồi tìm thấy thần tuyền nơi sơ đại của Yêu Long đạo môn đang bế quan. Dù hơn mười tu sĩ Thần Hỏa cảnh ra mặt xua đuổi, hắn vẫn nhìn sơ đại đã thành thần bằng ánh mắt thèm khát như đang thấy thức ăn, mở ra cuộc đối đầu mới."},{"chuong":815,"tieuDe":"Trận Đầu Thành Thần","tomTat":"Thạch Hạo trong hình dạng cháy đen tiến đến thần tuyền do Yêu Dịch và các tu sĩ Yêu Long đạo môn chiếm giữ, rồi bẻ gãy một pháp khí cấp Thần bằng tay không. Yêu Dịch dùng cốt kính nhận ra dấu hiệu tội huyết trên người hắn, còn các đồng môn liên tục nhục mạ và hợp lực công kích. Sau khi phá hủy Thiên La tán, Thạch Hạo chiếm thần tuyền, hấp thu vật chất thần tính và để lộ một trăm lẻ tám vết thương chứa thánh diễm, xác nhận hắn đã bước đầu thành thần. Hắn dựa vào tốc độ và sức chiến đấu áp đảo để giết sạch nhóm cường giả Thần Hỏa cảnh của Yêu Long đạo môn. Yêu Dịch hiện bản thể giao long và thi triển Yêu long trói trời, nhưng xích thần bị cánh Côn Bằng phá đứt. Thạch Hạo dùng tràng vực Côn Bằng giam đối thủ rồi chém đầu Yêu Dịch, hoàn tất trận chiến đầu tiên sau khi bước vào Thần cảnh."},{"chuong":816,"tieuDe":"Việc Ăn Uống Là Quan Trọng Nhất","tomTat":"Sau khi đánh tan nhóm Yêu Long đạo môn và giết Yêu Dịch, Thạch Hạo công khai đôi cánh sau lưng là bảo thuật Côn bằng mà đối phương muốn chiếm đoạt. Hắn luyện hóa gần cạn dòng suối chứa tinh hoa thần tính để phục hồi thân thể bị một trăm lẻ tám luồng đạo hỏa thiêu đốt, dù nguy cơ cạn kiệt nguyên khí vẫn còn. Không thể thu lấy bảo thuật thiên phú đã tan biến của Yêu Dịch, Thạch Hạo dùng cốt đỉnh màu tím hầm rồi ăn sạch thi thể giao long để hấp thu tinh hoa bản nguyên. Hắn tha mạng có điều kiện cho một cao thủ Yêu Long đạo môn giả chết, buộc người này dẫn đường tới tiểu thế giới sinh cơ nơi từng xuất hiện người Minh thổ. Trên đường tìm kiếm, Thạch Hạo hái nhiều bảo dược và tiếp tục hồi phục thương thế trước khi phát hiện Minh khí cùng dấu vết giao chiến. Hắn gặp lại Hồng Hoàng khi nàng đang bị nhóm Minh tộc cướp thánh dược và truy sát; nàng kinh ngạc vì từng tin hắn đã chết nhưng nhanh chóng xác nhận hắn còn sống. Thạch Hạo quyết định đối phó nhóm Minh tộc, còn Hồng Hoàng an tâm đứng sau hắn trước cuộc giao chiến sắp tới."},{"chuong":817,"tieuDe":"Minh Tộc","tomTat":"Hồng Hoàng bị một toán sinh linh Minh tộc bao vây, nhưng Thạch Hạo dùng bảo thuật Lôi đế mang tính dương cương quét sạch con mực, đầu lĩnh hình người và toàn bộ Minh nhân tại chỗ. Một chàng trai mặc giáp máu dẫn chó Địa ngục ba đầu đến ứng chiến dưới danh nghĩa Hắc Ám Thần tử, song con chó bị lực Côn Bằng đá nổ còn chủ nhân bị chiến kích Hư không chặn đường đào tẩu và giết chết. Trước khi chết, chàng trai dùng cốt kính ghi hình thần Thạch Hạo rồi truyền cho Hắc Ám Thần tử, qua đó mở ra nguy cơ đối đầu giữa hai người. Hồng Hoàng tiết lộ Hắc Ám Thần tử có thể là xác cổ từ kỷ nguyên trước, sở hữu thân thể kim cương bất hoại và những thần thông tự hình thành sau khi thức tỉnh. Sau trận chiến, Thạch Hạo tìm được ba cây thánh dược, trả lại cây của Hồng Hoàng và giữ một cây đỏ cùng Khuyển Diệp đằng để chữa thương. Từ suy đoán nơi đây có thể cất giấu vườn thuốc Tiên cổ, hai người tiến vào khu di tích dưới huyết nguyệt và bắt gặp một con rùa trắng cõng cô gái áo trắng xuất hiện giữa dược hương nồng đậm, khiến họ chấn động như sắp vũ hóa phi thăng."},{"chuong":818,"tieuDe":"Hư Thiên Thần Đằng","tomTat":"Thạch Hạo và Hồng Hoàng nhìn thấy rùa trắng chở một cô gái áo trắng tí hon, nhưng Thạch Hạo dùng Võ đạo Thiên nhãn cùng Trùng đồng xác định đó là huyễn cảnh do một cây thần dược tạo ra. Hồng Hoàng nhận diện cây thuốc là Hư Thiên thần đằng, thần dược có thể chữa thương gần chết, tăng đạo hạnh và mê hoặc người hái thuốc. Hai người tiến sâu qua vườn thuốc gồm nhiều tầng không gian, tìm được Hoàng Kim thảo và Sa Mạc ngân nhưng nhiều lần suýt chết bởi tàn trận. Tại tầng thứ năm, họ thấy bản thể Hư Thiên thần đằng đang bị một đại trận đủ sức giết Thiên Thần giam giữ. Thạch Hạo quyết đoạt cây thuốc để hộ mạng khi tiếp tục đốt cháy đại đạo trên ba ngàn con đường đá, nên quay lại gọi Đả Thần Thạch và mang theo Hoàng điệp. Đả Thần Thạch nhận lời phá trận để đổi lấy Hỗn Nguyên thạch, chịu nhiều lần phản kích rồi cuối cùng làm tan rã trận văn. Ngay khi đường vào vừa mở, một thanh niên ngân bào nghi là sơ đại xuất hiện, đuổi nhóm Thạch Hạo đi và định chiếm lấy thành quả."},{"chuong":819,"tieuDe":"Sơ Đại Thành Thần","tomTat":"Lạc Đạo và Lam Nhất Trần xuất hiện tại khu thần dược vừa được phá trận, tuyên bố sẽ giết hoặc thu phục nhóm Thạch Hạo rồi chia nhau chiến lợi phẩm. Hồng Hoàng nhận ra cả hai đều là cường giả đã thành thần nên khuyên Thạch Hạo rút lui, nhưng hắn bình tĩnh thách họ cùng xuất thủ. Thạch Hạo không dùng miễn dịch pháp lực mà trực tiếp đấu pháp lực và bảo thuật, sau hàng chục lần va chạm đã đánh lui Lạc Đạo. Lạc Đạo rút Tước Cốt kiếm và dùng tóc đỏ quấn vào cánh tay đối thủ, qua đó để lộ thần thông thiên phú thật sự nằm trong tóc, còn thanh kiếm chỉ là bí bảo do sư môn ban cho. Thạch Hạo truyền bảo thuật Luân hồi ngược qua sợi tóc, khiến Lạc Đạo già nua tức khắc, phù văn tiêu tan và sinh mệnh gần cạn kiệt. Hắn đạp Lạc Đạo dưới chân, buộc đối phương lựa chọn thần phục hoặc chết, rồi quay sang yêu cầu Lam Nhất Trần trở thành kẻ hầu. Những người quan sát ở ngoại giới kinh hãi khi lần đầu chứng kiến Thạch Hạo thi triển bảo thuật Luân hồi tại thượng giới."},{"chuong":820,"tieuDe":"Đắc Thủ","tomTat":"Thạch Hạo dùng Côn Bằng cực tốc, Súc địa thành thốn và Lôi đạo chặn đánh Lam Nhất Trần, trong khi Đả Thần Thạch tiếp tục trấn áp Lạc Đạo. Sau khi đánh bại hai sơ đại, hắn công khai mình chính là Hoang, đời sau tội huyết và Thạch Hạo, rồi buộc họ tạm thời hỗ trợ tìm thánh dược cùng thần tuyền bất tử trong Tiên cổ. Đả Thần Thạch đề nghị dùng Loạn Trận thuật để đề phòng hai người phản bội. Khi Lam Nhất Trần và Lạc Đạo tiến vào vườn thuốc, đại trận được Hư Thiên thần đằng kích thích bằng huyết tế bất ngờ bùng phát, chém Lam Nhất Trần thành hai đoạn trước khi hắn nối lại thân thể kim loại. Đả Thần Thạch phá bỏ trở ngại cuối cùng và dùng trận pháp ngầm chặn đường độn thổ, giúp Thạch Hạo bắt được Hư Thiên thần đằng rồi thu cả bảo thổ vào đỉnh. Hồng Hoàng rời đi tìm Lam Vũ và Oánh Oánh, còn hai sơ đại báo tin Hắc Ám Thần tử, truyền nhân Tiên điện cùng nhiều người đã tiến vào vùng sâu, nơi xuất hiện dấu vết sào huyệt Thập Hung. Thạch Hạo sau đó mang Đả Thần Thạch và Hoàng điệp trở lại con đường đá, ngồi xuống bế quan với ý niệm lấy thiên địa làm lò và vạn đạo làm lửa."},{"chuong":821,"tieuDe":"Vượt Ải","tomTat":"Thạch Hạo biết con đường đá từng khiến nhiều thiên tài cổ đại tọa hóa, bị phế hoặc gặp chuyện ngoài ý muốn nhưng vẫn quyết định tiếp tục vượt ải. Trước khi bế quan, hắn trao cây thánh dược đỏ đoạt từ Minh tộc cho Hoàng điệp để thực hiện lời hứa giúp nó lột xác, đồng thời nhắc Đả Thần Thạch rằng nó đã nhận Thiên Mệnh thạch và Hỗn Nguyên thạch. Sau năm ngày điều tức, hắn lấy thiên địa làm vật liệu, dùng hư không dựng lò rồi dẫn đạo hỏa từ các con đường đá vào nung luyện thân thể và nguyên thần. Số đạo hỏa tăng từ một trăm lẻ tám lên chín trăm, khiến thân thể hắn nhiều lần cháy đen, khô quắt và thủng xuyên, nhưng hắn vẫn chỉ quan sát đạo tắc để dùng chúng làm lửa hình thành chân ngã riêng. Để duy trì quá trình gần như tự sát này, hắn lần lượt tiêu hao Khuyển Diệp đằng, Hoàng Kim thảo, Sa Mạc ngân, hơn mười con giao long cùng lá và cuống Hư Thiên thần đằng. Hoàng điệp lo lắng và đem phần thánh dược đỏ còn lại tới giúp nhưng bị hắn từ chối. Khi đạt mốc chín trăm đạo hỏa, Thạch Hạo nhìn thấy những hình ảnh chấn động ẩn trong dấu ấn của Hư Thiên thần đằng. Thần dược nhắc lại lời thề không ăn sạch mình, còn hắn xác nhận chỉ lấy một phần để trị thương đại đạo."},{"chuong":822,"tieuDe":"Quỷ Biến","tomTat":"Hư Thiên thần đằng truyền cho Thạch Hạo những dấu ấn về Diệp Thiên Vũ và Mô Vô Đạo, hai cường giả đã vượt lôi kiếp nhưng ngay sau đó đều gặp biến cố kỳ quái rồi mất tích. Từ những trường hợp này cùng số phận của Ma tôn, Thạch Hạo nhận ra kỷ nguyên hiện tại không hẳn thiếu khả năng trường sinh, mà người tiến tới cửa ải cuối có thể bị quỷ biến can thiệp. Hư Thiên thần đằng còn kể về Ngũ Quan vương, người thử thành thần bằng bản nguyên Ngũ hành nhưng sau nhiều lần gặp quỷ biến đã biến đổi đôi mắt rồi mất tích. Nó cảnh báo Tiên cổ dễ phát sinh tai họa này và con đường khác thường của Thạch Hạo càng làm nguy cơ tăng cao. Thạch Hạo vẫn quyết định tiếp tục, chịu hơn một ngàn ánh lửa thiêu đốt thân thể và nguyên thần đến gần chết rồi phải dùng thần dược cứu mạng. Khi hắn chuẩn bị xung kích mốc một ngàn một trăm ánh lửa, Đả Thần Thạch và Hư Thiên thần đằng đồng thời phát hiện quỷ biến đang kéo tới."},{"chuong":823,"tieuDe":"Kỳ Dị","tomTat":"Trong lúc Thạch Hạo dùng một ngàn một trăm ánh lửa luyện thân trên ba ngàn con đường đá, đạo hỏa đột ngột rút đi và một luồng sương xám âm hàn xuất hiện, hủy những cây linh dược đặt gần đó. Được Hư Thiên thần đằng cảnh báo và cung cấp dược lực, hắn mở Động thiên duy nhất chống lại những xúc tu cùng trường mâu do sương hóa thành. Khi chịu lôi điện công kích, vật chất kỳ dị chuyển sang màu máu, ngưng tụ thành một con mắt yêu tà và phóng huyết quang. Thạch Hạo phát huy Bảo thuật Lôi đế, thi triển Cửu thiên Kiếp quang xuyên thủng con mắt đỏ, nhưng vẫn không xác định được bản chất của kẻ tập kích. Bất chấp lời khuyên rời đi, hắn kiên quyết tiếp tục dẫn thêm nhiều đợt đạo hỏa thiêu thân, dùng thần dược hồi phục và cảm nhận bản thân ngày càng mạnh hơn. Đến lúc một ngàn bốn luồng ánh lửa được dẫn tới, phù văn trong hư không hợp thành một chiếc đèn cổ giống như tọa độ chỉ dẫn. Tiếng bước chân sau đó vang lên, một bóng người thần bí từ cuối con đường đá chậm rãi tiến tới, khiến Thạch Hạo chuẩn bị đối mặt với thực thể mà hắn nghi là chính chủ."},{"chuong":824,"tieuDe":"Sinh Linh Kỳ Lạ","tomTat":"Một sinh linh hình người không có hơi thở hay dao động sinh mệnh xuất hiện từ sương xám theo tọa độ do chiếc đèn quy tắc tạo thành. Hư Thiên thần đằng nhận ra hiện tượng quỷ biến và cảnh báo đối phương có thể phá hỏng đạo cơ của Thạch Hạo. Sinh linh kỳ lạ dùng chiến mâu đồng giao đấu ngang sức với Thạch Hạo, đồng thời lần lượt tái hiện lôi điện, cánh Côn Bằng và phù văn Luân Hồi tương ứng với sở học của hắn. Sau hai ngàn hiệp, Thạch Hạo gần kiệt sức nên chuyển sang đồng thời triển khai Luân Hồi thuật, bảo thuật Lôi đế, pháp môn Côn Bằng và Thượng Thương kiếp quang, đánh rạn nứt thân thể đối phương. Hắn tiếp tục hợp nhất cánh Lôi điện, cánh Côn Bằng và Súc địa thành thốn để đạt tốc độ cực hạn, rồi dùng chiến kích Hư không xuyên thủng ngực và ghim sinh linh xuống đất. Khi sương đen tan đi, Thạch Hạo phát hiện đối phương có dung mạo giống hệt mình lúc già, mặc trang phục Tiên cổ và mang một đoản mâu cổ xuyên từ mi tâm qua não."},{"chuong":825,"tieuDe":"Chém Chính Mình","tomTat":"Thạch Hạo đối diện một sinh linh già nua có dung mạo, khí tức và bảo thuật gần như giống hệt mình, nhưng kịp nhận ra tâm trạng đang bị sức mạnh kỳ dị chi phối. Hắn hóa giải Luân Hồi thuật của đối phương bằng cốt văn, Miễn dịch pháp lực và Nguyên thủy chân giải, sau đó dùng đại kích chém sinh linh quỷ biến thành hai nửa. Nhận thấy cổ đăng trên cao có thể là mốc tọa độ của hiện tượng quỷ biến, hắn dùng lôi điện cùng Chiến kích Hư không phá đèn rồi luyện sạch mọi mảnh phù văn và tàn tích. Bất chấp lời can ngăn của Đả Thần Thạch và Hư Thiên thần đằng, Thạch Hạo tiếp tục dẫn ánh lửa từ các con đường đá nung luyện huyết nhục lẫn nguyên thần, nhiều lần lâm vào cảnh cửu tử nhất sinh. Khi đạt một ngàn năm trăm ánh lửa và hồi phục hơn mười ngày, hắn phát hiện mình đã đột phá lên Thần Hỏa cảnh trung kỳ. Do thần dược dự trữ đã cạn, Thạch Hạo quyết định xuất quan tìm Lam Nhất Trần và Lạc Đạo, đồng thời kiểm nghiệm thành quả bế quan. Hư Thiên thần đằng sau đó tiết lộ một vườn thuốc thần bí có Chu quả, Kỳ Lân thụ và Trường Sinh tiên dược từng thuộc về Tiên."},{"chuong":826,"tieuDe":"Quang Minh Thành","tomTat":"Hư Thiên thần đằng tiết lộ vườn thuốc Tiên cổ thần bí có Trường Sinh dược nhưng di chuyển trong hư không và nguy hiểm tới mức có thể giết cả Thiên Thần, khiến Thạch Hạo quyết định tiếp tục tăng thực lực trước khi thăm dò. Đả Thần Thạch cho biết họ đã vào Tiên cổ được một năm rưỡi, còn Hoàng điệp đã kết kén hoàng kim và ngủ say sau khi ăn hết cây thánh dược giống san hô đỏ. Kết thúc bế quan ở Thần Hỏa cảnh trung kỳ, Thạch Hạo lần theo địa chỉ Lam Nhất Trần và Lạc Đạo để lại, vượt qua nhiều tiểu thiên thế giới và tới Quang Minh thành. Tại trung tâm giao dịch này, hắn biết các phe liên quan tới quái thai cổ đại, Tiên điện và Hắc Ám thần tử đang chiếm ưu thế, trong khi giao chiến chỉ được phép diễn ra ngoài thành. Một chủ sạp cố ý dụ hắn ra ngoài để những kẻ đang truy tìm Lam Nhất Trần và Lạc Đạo vây giết, nhưng hơn ba mươi kẻ lần lượt bám theo đều không trở lại. Thạch Hạo quay về trong lúc ăn đùi Hoàng Kim loan, khiến chủ sạp hoảng sợ xin tha, giao thánh dược và tiết lộ Lam Nhất Trần cùng Lạc Đạo đang bị săn lùng vì giữ Bát Trân Kỳ. Biết nhiều thế lực muốn chiếm sinh linh có khả năng làm dược hiệu tăng lên nhiều lần và còn đe dọa chủ nhân của nó, Thạch Hạo nổi giận, chuẩn bị đối đầu các phe tranh bảo."},{"chuong":827,"tieuDe":"Ma Vương Xuất Hành","tomTat":"Thạch Hạo khiến chủ sạp Lộ Dịch kinh sợ rồi hứa cho hắn gia nhập thế lực mà mình dự định dựng nên tại Quang Minh thành. Được Lộ Dịch dẫn đường, hắn tới Hắc Ám thần cung để truy tìm tung tích Lạc Đạo và Lam Nhất Trần nhưng bị Lão Minh nhân dùng truyền tống trận đưa vào sát trường ngoài thành. Thạch Hạo dùng cực tốc bám theo đường an toàn của đối phương, giết Lão Minh nhân và quét sạch lực lượng Minh tộc mai phục trong đại trận. Trở lại thành, hắn khảo sát Long cung cùng các thế lực đứng sau quái thai cổ đại rồi quyết định tới Tiên điện chất vấn việc truy sát hai cố nhân và tranh đoạt Bát Trân Kỳ. Người của Tiên điện định dùng Phá Không phù cưỡng ép đưa hắn ra ngoài thành để giết kín, còn Hạc vàng dựa vào đại nhân Tiên điện sắp xuất quan để đe dọa hắn. Thạch Hạo lập tức kéo Hạc vàng tới và liên tiếp tát đối phương trước sự kinh hãi của đám đông. Ngoài Tiên cổ, các giáo chủ tiếp tục khắc tên lên cánh hoa Tiên đạo nhưng không thể dò xét nhiều thiên tài đang bế quan vì họ được đại đạo và sương mù che giấu."},{"chuong":828,"tieuDe":"Cướp Sạch Tiên Điện","tomTat":"Thạch Hạo công khai trấn áp Hạc vàng trước cứ điểm Tiên điện, phá tan cốt văn hộ thể và chấn lui những người định cứu viện. Hắn ép Hạc vàng mở bảo khố rồi lấy tám cây thánh dược, hai quả bán thần, Vân Văn đạo đồng cùng nhiều thần liệu quý. Hành tung của Hoang hiện lên trên cánh hoa và bia đá tại biên giới khu vực không người, khiến tu sĩ các giáo chấn động và người của Tiên điện nổi giận. Hai Tiên tướng trở về, dùng Phá Không phù đưa Thạch Hạo và Lộ Dịch ra ngoài thành để cùng hơn mười cường giả vây giết, nhưng toàn bộ lực lượng này bị Thạch Hạo tiêu diệt. Trở lại Quang Minh thành, Thạch Hạo định cướp Hắc Ám thần cung thì gặp Lạc Đạo. Biết Lam Nhất Trần đang mang Bát Trân Kỳ và bị vây trong một mỏ quặng kim loại, hắn lập tức giương cánh Côn Bằng lên đường cứu viện."},{"chuong":829,"tieuDe":"Ngân Ma Sơn","tomTat":"Thạch Hạo cùng Lạc Đạo và Lộ Dịch tiến vào Ngân Ma sơn, nơi Lam Nhất Trần đang mang Bát Trân Kỳ và dùng thiên phú hòa vào kim loại để trốn tránh nhiều thế lực. Sau khi biết Hỏa Vân động, Hắc Ám thần cung, Kiếm cốc cùng nhiều sơ đại và tán tu tham gia săn đuổi, Thạch Hạo tuyên bố sẽ giết mọi kẻ cản đường. Hắn dùng cánh Côn bằng đánh tan cửa ải đầu tiên, còn Lạc Đạo thi triển tóc đỏ phá cốt khí, bảo thuật và giết sạch nhóm trấn giữ nhận ra mình. Khi lực lượng mai phục kéo đến vây công, Thạch Hạo dùng Thượng Thương kiếp quang giết hơn ba mươi người, khiến những kẻ còn lại sợ hãi lui bước. Nhóm ba người vượt qua bốn cửa ải rồi tới đại trận do các thế lực đỉnh cấp bố trí quanh ngọn núi trung tâm. Dựa vào hiểu biết trận pháp tích lũy khi đồng hành với Đả Thần Thạch, Thạch Hạo đánh vào điểm yếu và xé một góc trận để tiến vào. Tại trung tâm, hắn đối mặt tám cường giả, khẳng định Lam Nhất Trần là người mình phải đưa đi và Bát Trân Kỳ vốn thuộc về mình. Những người đối diện không chịu nhượng bộ, thậm chí cô gái giáp đỏ còn đề nghị giết Thạch Hạo để biến kỳ trân thành vật vô chủ."},{"chuong":830,"tieuDe":"Tám Đại Cao Thủ","tomTat":"Thạch Hạo đến Ngân Ma sơn và xác nhận tám chí cường giả đang chặn đường mình, trong đó có bốn sơ đại cùng bốn người đủ sức giao chiến với sơ đại. Sư tử trắng thay mặt Thần miếu mời hắn kết minh, nhưng cuộc thương lượng đổ vỡ khi phía đối phương muốn hắn nhường Bát Trân Kỳ cho Cổ thánh tử. Hoàng Kim ngưu tranh quyền ra tay trước, song bị Thạch Hạo áp đảo về sức mạnh thân thể, phá vỡ trường đao và để lại Long Trảo ấn gần xuyên thủng tim. Nhận ra không ai có thể dễ dàng thắng riêng lẻ, tám cao thủ quyết định hợp lực vây giết Thạch Hạo, còn hắn yêu cầu Lạc Đạo lui lại để tự mình nghênh chiến. Trong đợt giao phong đầu tiên, Thạch Hạo đánh bật lông thần của Long tước, phá quạt lửa và đánh trọng thương cô gái mặc giáp đỏ, đồng thời áp chế Sư tử trắng. Trước câu hỏi về thân phận, hắn công khai tên thật Thạch Hạo và quyết dùng trận chiến này gây dựng uy danh cho chính mình thay vì chỉ dựa vào danh hiệu Hoang."},{"chuong":831,"tieuDe":"Ma Vương Vô Địch","tomTat":"Thạch Hạo một mình đối đầu tám cao thủ sơ đại tại Ngân Ma sơn, lần lượt hóa giải chiến kỹ mượn sức đại địa, thần kiếm, đuôi độc và thần thông không gian của đối phương. Hắn dùng Kim Tuyền Ba Văn Công ép nữ sơ đại Hỏa Hạt tộc tự bẻ đuôi, rồi vận dụng Bảo thuật Lôi Đế khắc chế nữ cường giả Minh tộc và khiến thân phận Hoang dần bị nhận ra. Thượng Thương kiếp quang xuyên thủng đầu lâu Tam Nhãn thú, mở đầu cuộc đại khai sát giới. Thạch Hạo tiếp tục dùng Động thiên duy nhất chống hai loại âm hống, giết Hoàng Kim ngưu bằng mâu lôi điện và chém đầu Sư tử trắng bằng Luân Hồi thuật. Sau đó hắn dùng cánh Côn Bằng diệt cả thân thể lẫn nguyên thần Long tước, cầm chiến kích Hư không truy sát và bổ đôi nữ cường giả Minh tộc, rồi chặt chín đuôi và chém đầu nữ sơ đại Hỏa Hạt tộc. Trước chiến lực áp đảo ấy, những người còn sống tìm đường bỏ chạy, còn Lạc Đạo và Lam Nhất Trần lần đầu cảm thấy việc đi theo Thạch Hạo không phải là oan ức."},{"chuong":832,"tieuDe":"Nồi Lẩu","tomTat":"Thạch Hạo cùng Lạc Đạo và Lam Nhất Trần truy sát hai sơ đại cuối cùng tại Ngân Ma sơn, không để bất kỳ ai thoát khỏi chiến trường. Đả Thần Thạch phá ý đồ dùng Phá Không phù của Ngân giao, giúp Thạch Hạo dùng Chiến kích Hư không đánh chết đối phương. Hắn tiếp tục thi triển Tán thức của Kim Xà thối, phá tan kiếm khí và chém đôi Tử Kim hộc. Kết quả tám cao thủ cấp sơ đại cùng ngã xuống khiến các thế lực theo dõi bên ngoài Tiên cổ chấn động và làm những tộc mất truyền nhân vô cùng phẫn nộ. Các bá chủ cổ đại sau đó tranh luận về con đường vượt cực hạn Thần Hỏa cảnh, trong khi đại diện Hoàng tộc đương đại xác nhận nhiều cổ giáo đã dồn tích lũy cho quái thai cổ đại. Sau khi đại trận quanh núi được phá giải, Lộ Dịch tìm thấy linh tuyền còn Thạch Hạo sai mọi người xử lý thi thể các mãnh thú và chim thần. Cả nhóm dùng đỉnh nấu lẩu với thịt Hoàng Kim ngưu, khiến Lộ Dịch hấp thu dược lực đến mức thất khiếu phát kim quang. Khi chuẩn bị thêm thịt Hỏa Hạt, Thạch Hạo cảnh báo mọi người phải loại bỏ nọc độc ở đuôi để tránh gây họa cho cả nhóm."},{"chuong":833,"tieuDe":"Ăn Cướp","tomTat":"Sau trận chiến tại Ngân Ma sơn, Thạch Hạo cùng Lạc Đạo, Lam Nhất Trần và Lộ Dịch mở tiệc bằng huyết nhục của nhiều sơ đại, trong đó thịt Hỏa Hạt phải được xử lý cẩn thận vì độc tố có thể giết Chân Thần. Thạch Hạo giữ lại Nguyên thủy chân vũ của Long tước và Tử Kim hộc để chuẩn bị tế luyện lại quạt Ngũ Cầm. Lam Nhất Trần giao Bát Trân Kỳ cho hắn nhằm hỗ trợ kế hoạch vượt cửa ải, còn Thạch Hạo chia Vân Văn đạo đồng lấy từ Tiên điện cho hai đồng bạn. Khi viện binh các thế lực đến Ngân Ma sơn, nhóm người đã rời đi và mọi dấu vết quan trọng đều bị thiêu sạch. Trở lại Thành Quang Minh, Thạch Hạo công khai phá cứ điểm Hắc Ám thần cung, cướp bảo khố và truy hỏi nơi bế quan của Hắc Ám thần tử nhưng không có kết quả. Hắn tiếp tục cướp thêm một cứ điểm khác, rồi nghe Lạc Đạo báo Ninh Xuyên có thể sắp quay lại. Thay vì tránh né, Thạch Hạo lập tức quyết định tìm đến thế lực của Ninh Xuyên trong thành."},{"chuong":834,"tieuDe":"Xương Cánh Tay","tomTat":"Ngoại giới không thể quan sát trọn vẹn những người đang lột xác sâu trong Tiên cổ, nhưng hình ảnh Ninh Xuyên bất ngờ xuất hiện trên bia đá khi hắn chuẩn bị một lần dung hợp nguy hiểm. Hắn mở hộp báu chế từ lõi Thế Giới thụ, dùng máu kích hoạt khúc xương cánh tay cổ rồi xé cánh tay trái để dung hợp nó vào cơ thể, khiến cốt văn lan dọc xương tay trước khi thiên cơ lại che khuất hình ảnh. Tại Quang Minh thành, Thạch Hạo dẫn Lạc Đạo và Lam Nhất Trần đánh vào phủ Ninh Xuyên để tính món nợ từng bị vây công. Thạch Hạo dùng quyền đánh nổ khôi lỗi có chiến lực Chân Thần, phá bảo khố và lấy mười một cây thánh dược, năm bán thần quả cùng nhiều tài nguyên khác. Một sứ giả của Đọa Thần lĩnh thay Đọa thần tử đề nghị kết minh, nhưng Thạch Hạo đáp lại bằng yêu cầu phe này dựng phủ và gom đủ tài vật rồi mới tới tìm mình. Tin Hoang đang cướp bảo khố khiến người trong thành tháo chạy, làm kế hoạch tiếp tục tính sổ của hắn bị gián đoạn. Vì số tài nguyên vừa lấy vẫn không đủ cho con đường tu luyện mong muốn, Thạch Hạo quyết định tới sào huyệt nghi của Thập Hung tìm thần dược và tuyên bố sẽ chém Ninh Xuyên nếu đối phương xuất hiện."},{"chuong":835,"tieuDe":"Sào Giới","tomTat":"Thạch Hạo cùng Lộ Dịch, Lam Nhất Trần và Lạc Đạo tiến sâu vào khu rừng nguyên thủy của Sào giới để tìm đường tới Hung sào. Khi ngọn núi đá được chọn làm nơi nghỉ chân bất ngờ lộ ra là vỏ của Ốc sên thôn thiên, Thạch Hạo kịp thời dùng phù văn vàng đưa cả nhóm rút xa, tránh chất nhầy có thể phá hủy đạo cơ và giết cả Thiên Thần. Trên đường đi, họ bàn luận về sự khép kín của các sinh linh nguyên thủy Tiên cổ và số phận bất thường của hậu duệ những thiên tài từng lưu lại nơi này. Cả nhóm sau đó vượt qua Quỷ lâm, nơi sức mạnh kỳ dị tác động lên nguyên thần và khiến Lộ Dịch suýt quên tên mình, trong khi động thiên bảo vệ Thạch Hạo khỏi ảnh hưởng. Khi tới gần Hung sào, họ nhìn thấy ba mươi ba huyết nguyệt, mười huyết nhật và ba ngàn ngôi sao màu lam vấy máu, được xem là dấu tích của đại chiến cuối kỷ nguyên Tiên cổ. Thạch Hạo nhận ra sào huyệt tưởng như ở ngay trước mắt thực tế bị nhiều lớp không gian ngăn cách, đồng thời phát hiện hồ Linh dịch có Phượng ngư, Thần Quả thụ và cung điện cổ trên dòng sông sinh mệnh."},{"chuong":836,"tieuDe":"Dồn Dập Xuất Quan","tomTat":"Cổ lộ phát sáng cưỡng chế đưa nhóm Thạch Hạo tới một khu vực bí cảnh có linh khí nồng đậm, linh dược sinh trưởng dày đặc nhưng chịu pháp tắc kỳ lạ ngăn cản hóa hình. Khi bị hơn mười sinh linh đã thành thần chặn cướp, Lam Nhất Trần đánh trọng thương chúng và cả nhóm lấy lại số thánh dược mà chúng từng đoạt của người khác. Trong sáu ngày tiếp theo, Thạch Hạo, Lạc Đạo và Lam Nhất Trần vượt qua nhiều khu vực, tiêu diệt những toán tu sĩ chủ động chặn đường và tích lũy lượng lớn chiến lợi phẩm. Lộ Dịch quyết định tiếp tục theo nhóm, phụ trách dò xét tin tức các thế lực và tiêu thụ những vật đồng đội không cần. Cùng lúc đó, thiếu niên song cốt của Tần tộc mặc Chiến y Trường sinh rời hang cổ để tìm Hung sào, khiến ngoại giới phát hiện một khối cốt trong cơ thể hắn có thể là tiên cốt. Thạch Nghị cũng kết thúc nhiều năm ngủ đông trên ngọn núi đen, thức tỉnh toàn bộ thần năng Trùng đồng và tuyên bố tranh vị vô địch. Cuối cùng, Ninh Xuyên rời động phủ để hướng tới Hung sào, đồng thời công khai tuyên bố sẽ đích thân giải quyết Hoang."},{"chuong":837,"tieuDe":"Khu Rừng Thần Quả","tomTat":"Thạch Hạo dẫn Lạc Đạo, Lam Nhất Trần và Lộ Dịch đi sâu vào vùng núi bên ngoài Thập Hung sào, nơi họ bắt gặp hàng nghìn thần thi rồi một cốt địa chứa hơn hai vạn bộ hài cốt. Cả nhóm phát hiện một sơ đại Thần Hỏa đại viên mãn chỉ còn chút chấp niệm, mang những vết thương do lôi điện và chết ngay sau khi cầu cứu. Một con sâu đen có cánh từ đầu lâu lao vào mắt Thạch Hạo nhưng bị hắn dùng ký hiệu sấm sét vàng óng đánh chết. Dù Lam Nhất Trần đề nghị rút lui, Thạch Hạo vẫn tiếp tục điều tra và đánh thức Đả Thần Thạch để quan sát đại trận cổ ở cuối cốt địa. Cả nhóm vượt qua một lỗ hổng của trận pháp, tiến vào vùng đất tràn ngập thánh quang và phát hiện hàng chục Thần Quả thụ mang quả hình người nhiều màu. Thạch Hạo hy vọng thần quả có thể bù đắp hao tổn của mình, nhưng vẫn cảnh giác trước nguyên nhân khiến vô số người chết trên đường tới đây và yêu cầu đồng bạn đứng sát bên trước khi thử hái quả."},{"chuong":838,"tieuDe":"Điên Cuồng","tomTat":"Thạch Hạo dẫn Lạc Đạo, Lam Nhất Trần và Lộ Dịch tiến vào rừng Bán Tham quả thụ, nhưng khí lành cùng hương thơm nơi đây lại che giấu sát cơ từ những Quỷ Quái thần khó bị công kích vật lý tiêu diệt. Khi hàng chục bóng đen, trong đó có nhiều Chân Thần, vây kín cả nhóm, Thạch Hạo dùng Bảo thuật Lôi Đế và sức mạnh cương dương để chống trả, song vô số Hắc Thần trùng nhanh chóng xuất hiện, phá tan mây sét và điều khiển đám quỷ vật tấn công dữ dội hơn. Lạc Đạo, Lam Nhất Trần và Lộ Dịch lần lượt trọng thương trước đàn sâu, buộc Thạch Hạo phải thu họ vào Động thiên duy nhất, rồi mở lò luyện đan phóng nước sông cấm kỵ mang lôi đình, khí tức Tiên đạo và sức nguyền rủa để bức lui kẻ địch. Không cam lòng rời đi tay trắng, hắn vừa duy trì phòng hộ vừa điên cuồng nhổ tám cây cổ thụ, thu hơn hai chục Bán Tham quả dù liên tục bị đánh đến thổ huyết. Hành động ấy khiến đàn sâu đánh thức hai Hắc Thần trùng cấp Thiên Thần đang trầm miên trên tán cây, nhưng chúng vừa tỉnh lại đã phát điên, giết cả đồng loại lẫn Quỷ Quái thần. Lợi dụng cảnh hỗn loạn, Thạch Hạo hái thêm quả rồi dẫn mọi người phá vây bỏ chạy, song hai Thiên Thần cùng một vùng bóng đen vẫn bám sát truy sát phía sau."},{"chuong":839,"tieuDe":"Thắng Lợi Trở Về","tomTat":"Thạch Hạo cùng Lạc Đạo, Lam Nhất Trần và Lộ Dịch chạy khỏi rừng Thần quả dưới sự truy sát của đại quân Hắc Thần trùng, trong đó có hai cá thể cấp Thiên Thần phát điên. Cả nhóm thoát được khỏi phạm vi hoạt động của đàn sâu nhưng ba người đồng hành đều trọng thương, sau đó nhanh chóng phục hồi nhờ Bán Tham quả. Khi dò xét những con sâu bị bắt, Thạch Hạo chỉ cảm nhận được sự tàn bạo và trạng thái bán ma hóa, khiến mọi người nghi ngờ môi trường Tiên cổ đã làm các sinh linh ngoại lai biến đổi. Vì muốn dùng thần quả mở rộng con đường tu hành riêng, Thạch Hạo một mình quay lại rừng, đối đầu Hắc Thần trùng cùng Quỷ Ma thần và phát hiện dấu vết của một người từng hái quả trước đó. Hắn trải qua cuộc chiến sinh tử rồi mang đầy một sọt Bán Tham quả trở về, quyết định dừng lại vì dùng quá nhiều sẽ làm giảm dược hiệu. Trong lúc nhóm Thạch Hạo rời đi với chiến lợi phẩm, Tần Hạo, Trùng Đồng giả và Ninh Xuyên lần lượt xuất hiện quanh Hung sào, báo hiệu các thiên kiêu đang hội tụ cho cuộc tranh đoạt mới."},{"chuong":840,"tieuDe":"Tiến Quân Vào Hung Sào","tomTat":"Tần Hạo, Thạch Nghị và Ninh Xuyên lần lượt tiến sâu vào cổ địa bằng những năng lực riêng, trong đó Ninh Xuyên còn mang vòng xuyến sáu phù cốt để dò tìm hậu duệ tội huyết. Nhóm Thạch Hạo rời khu rừng Thần thụ rồi bị một liên minh dị tộc phục kích nhằm cướp thần quả, nhưng họ nhanh chóng đánh tan và tiêu diệt toàn bộ đối phương. Từ chiến lợi phẩm, cả nhóm thu được một bức tranh đá có thể chỉ dẫn đường đi, giúp tránh nguy hiểm và tìm nơi tạo hóa trong Hung sào. Sau nhiều ngày tìm kiếm cổ điện không thành và liên tục giao chiến, bốn người tới Vẫn Tiên lĩnh, con đường bắt buộc trước khi tiến vào Hung sào. Tại đây, Tần Hạo nghe người khác bàn luận về hai khối Chí Tôn cốt của mình nên nổi giận dùng bảo thuật giết hơn hai mươi sinh linh. Hắn tiếp tục lần theo một luồng tinh lực mạnh trong núi, rồi kinh hãi nhận ra người vừa để lộ dung mạo chính là Thạch Hạo."},{"chuong":841,"tieuDe":"Huynh Đệ","tomTat":"Tần Hạo kinh động khi nhận ra Thạch Hạo vẫn còn sống, sau đó gọi hắn là ca ca và báo rằng cha mẹ vẫn bình an. Thạch Hạo nhắc lại việc Lão Thập Ngũ từng bị Tần tộc giam cầm rồi đày tới đảo Ác Ma, đồng thời yêu cầu em trai điều tra và không nương tay với những kẻ có trách nhiệm. Qua bia đá, Tần Di Ninh xúc động rơi lệ khi thấy hai con đoàn tụ, còn Thạch Tử Lăng lạnh lùng nhìn về phía một số người Tần tộc. Thạch Hạo giấu nguyên nhân hồi sinh, xác nhận tổ phụ vẫn khỏe và tạm thời không hỏi tin A Man vì lo gây biến cố. Trên đường tới Hung sào, Tần Hạo dùng cốt văn hộ thể liên tục tăng tốc nhưng vẫn không thể bỏ lại Thạch Hạo đang mang theo các đồng bạn. Vì muốn vượt qua huynh trưởng, Tần Hạo đề nghị luận bàn và được Thạch Hạo chấp thuận. Trước khi hai anh em giao đấu, Thạch Hạo cảm nhận khí tức quen thuộc tại Vẫn Tiên lĩnh và phát hiện Thạch Nghị, trong khi đối phương cũng nhận ra hắn."},{"chuong":842,"tieuDe":"Ba Thạch","tomTat":"Tại Vẫn Tiên lĩnh, Thạch Hạo tái ngộ Thạch Nghị và nhận ra Trùng đồng của đối phương có khả năng đã quy nhất, với dị tượng đủ khiến nhiều người quan sát bị thương hoặc trầm luân thần hồn. Hai đối thủ cũ thừa nhận sức mạnh của nhau, đồng thời khuấy động cốt văn khiến toàn khu vực chấn động. Tần Hạo tiến lên khiêu chiến Thạch Nghị nhưng bị hẹn ba năm sau, qua đó khiến quan hệ huyết thống giữa ba chí cường trẻ tuổi của Thạch tộc được công khai. Ở Sào giới, Ninh Xuyên tiếp nhận đệ tử Hỏa Vân động và Yêu Long đạo môn rồi dẫn họ tới Vẫn Tiên lĩnh để săn hậu duệ tội huyết. Một tùy tùng dùng cốt kính chiếu vào vùng núi, khiến trán Thạch Hạo, Thạch Nghị và Tần Hạo đồng thời phát thánh quang và hiện chữ Tội trên trời. Trước mối đe dọa chung, ba người vốn đang đối đầu đều quay sang đoàn Ninh Xuyên."},{"chuong":843,"tieuDe":"Lục Quan Vương","tomTat":"Dấu ấn tội huyết của Thạch Hạo, Thạch Nghị và Tần Hạo đồng thời chiếu sáng trời cao, khiến phe Ninh Xuyên, sinh linh Vẫn Tiên lĩnh và những người quan sát bên ngoài cùng chấn động. Các giáo chủ nhận ra một mạch Thạch tộc có ba chí tôn trẻ tuổi sở hữu Trùng đồng, Tiên cốt và con đường chí tôn niết bàn, từ đó lo ngại họ có thể làm thay đổi bố cục Ba ngàn châu. Ba người lần lượt chất vấn căn cứ mà Ninh Xuyên cùng các đạo thống dùng để kết tội hậu nhân Thạch tộc. Ninh Xuyên chủ động giao thủ với Tần Hạo, dùng Bàn tay hóa bầu trời nghiền nát Mộc đại pháp, buộc Tần Hạo kích phát Tiên cốt và diễn biến Ngũ hành. Thạch Nghị sau đó dùng phù văn Trùng đồng phá hủy bí bảo cấp Thần, giết một người theo Ninh Xuyên rồi đối kháng Thái Âm thần cương của Lục Quan Vương. Sau màn thăm dò khiến vùng núi bên dưới bị cày nát, Thạch Hạo bước vào hư không và tuyên bố sẽ đích thân tiếp nhận trận chiến mà Ninh Xuyên vốn dành cho mình."},{"chuong":844,"tieuDe":"Tiểu Lục Tử","tomTat":"Ninh Xuyên tuyên bố đến trấn áp hậu nhân tội huyết rồi dùng Phiên Vân Phúc Vũ Thủ giao đấu thăm dò với Thạch Hạo, nhưng tán thủ hình rồng của đối phương khiến đòn đầu không phân thắng bại. Tần Hạo và Thạch Nghị cùng đứng ra bảo vệ danh dự Thạch tộc, trong đó Thạch Nghị cố ý gọi Ninh Xuyên là tiểu Lục tử rồi nhường cuộc đấu riêng cho Tần Hạo. Tần Hạo thi triển vòng tròn ngũ hành với sự hỗ trợ của chiến y Trường Sinh, buộc Ninh Xuyên phải thận trọng đối kháng. Khi những người đi theo Ninh Xuyên tiếp tục miệt thị huyết mạch Thạch tộc, Thạch Nghị dùng đại kích và Trùng Đồng thần quang giết gần hết bọn họ. Thạch Hạo dùng Côn Bằng pháp chặn Ninh Xuyên cứu viện rồi lấy Côn Bằng quyền đánh chết tên sơ đại cuối cùng. Ba người Thạch tộc sau đó quyết định hợp sức trấn áp Ninh Xuyên và lấy chân huyết của hắn làm tế phẩm mở con đường vào Hung sào. Tại ngoại giới, một ông lão bí ẩn tiết lộ rằng Tội châu chưa bị san bằng vì các thế lực vẫn chưa biết những người ở biên hoang đã chết hết hay còn có thể trở về."},{"chuong":845,"tieuDe":"Phong Thái","tomTat":"Tại Vẫn Tiên lĩnh, Ninh Xuyên mở Thiên thẩm phán, dùng xích thần hoàng kim khóa thần hồn Tần Hạo rồi tiếp tục điều động xích thần màu máu mang sát cơ. Tần Hạo chống trả bằng tiên kiếm ngũ hành nhưng bị áp chế, sau đó kích phát sức mạnh Tiên cốt và phá nổ cả hai loại xiềng xích. Ninh Xuyên công khai ý định đoạt Tiên cốt của Tần Hạo để phối hợp với xương tay của mình. Thạch Hạo và Thạch Nghị cùng ra tay phá thế áp chế rồi phối hợp với Tần Hạo vây đánh Lục Quan vương. Thạch Nghị dùng Bổ Thiên thuật hóa giải đòn tấn công và đánh xuyên vai Ninh Xuyên, còn Thạch Hạo thi triển Bảo thuật Lôi Đế khiến cánh tay phải đối thủ cháy đen. Dù liên tiếp bị thương, Ninh Xuyên vẫn cách không đánh trúng Tần Hạo khiến hắn chảy máu ở khóe miệng. Thạch Hạo trấn an em trai, nhắc rằng kinh nghiệm chiến đấu của Tần Hạo còn ít và đối phó Ninh Xuyên không thể nóng vội."},{"chuong":846,"tieuDe":"Ngã Xuống","tomTat":"Ninh Xuyên dùng thần huyết diễn hóa sương đỏ, biển máu, cốt văn và sát quang bao phủ chiến trường, thậm chí xóa bỏ nguyên thần của một số sinh linh quan chiến từ xa. Thạch Hạo mở Động thiên duy nhất, Thạch Nghị vận dụng Trùng đồng và Tần Hạo phát động thần quang Ngũ hành cùng bảo thuật từ khối cốt trong ngực để phá thế công, khiến Ninh Xuyên bị thương nặng. Ninh Xuyên lấy vòng xuyến Lục đạo chí tôn luyện từ sáu khối chân cốt ra, đồng thời tái hiện sáu đại thần thông để phản kích. Thạch Hạo và Tần Hạo phối hợp hai dạng Luân hồi, còn Thạch Nghị thi triển Vạn vật đều diệt; sau cuộc va chạm, vòng xuyến rời tay Ninh Xuyên và rơi xuống vùng núi nhưng chưa ai dám lấy. Thạch Hạo và Thạch Nghị tạm gác việc tranh bảo để ưu tiên tiêu diệt đối thủ. Trong đòn quyết chiến, kiếm ánh sáng Luân hồi xuyên thủng đầu Ninh Xuyên, cánh Côn Bằng chém lìa eo hắn, còn ánh sáng Trùng đồng tạo thêm hai lỗ máu trên thân thể. Tần Hạo vận dụng Tiên cốt nhưng bị đánh văng và liên tục thổ huyết. Cuối chương, bộ thân thể của Ninh Xuyên được xác nhận đã chết, song kết cục nguyên thần của hắn vẫn chưa rõ."},{"chuong":847,"tieuDe":"Chỉ Là Khởi Đầu","tomTat":"Linh thân áo trắng của Ninh Xuyên bị Thạch Hạo, Thạch Nghị và Tần Hạo đánh giết tại Vẫn Tiên lĩnh, khiến các sinh linh trong Tiên cổ cùng nhiều thế lực ngoại giới chấn động. Thạch Hạo cảnh báo rằng đối thủ vừa chết chỉ là linh thân, còn chân thân Lục Quan vương vẫn đang bế quan và mạnh hơn rất nhiều. Khi Thạch Nghị và Thạch Hạo cùng nhắm tới vòng xuyến gồm sáu khối chân cốt, một sinh vật cấp Thần định thừa cơ cướp bảo vật nhưng bị cả hai phát hiện và tiêu diệt. Đả Thần Thạch chen vào tranh bảo, song Thạch Nghị cuối cùng chủ động nhường vòng xuyến cho Thạch Hạo. Qua cảm ứng, Thạch Hạo phát hiện sáu khối chân cốt vẫn còn sinh cơ, có thể hấp thu tinh hoa thiên địa và tiếp tục tiến hóa, dù phù văn ẩn bên trong hiện chưa thể sử dụng. Trong lúc đó, chân thân Ninh Xuyên tại hang cổ hỗn độn thu hồi tàn dư linh thân và bình thản tuyên bố sẽ giải quyết mọi người sau khi xuất quan. Ba huynh đệ Thạch tộc tạm gác đề phòng lẫn nhau, cùng tiến về Hung sào giữa sự kinh hãi và chú ý của vô số cường giả đi theo phía sau."},{"chuong":848,"tieuDe":"Qua Ải","tomTat":"Thạch Hạo và Thạch Nghị dùng huyết dịch thần thánh kích hoạt một huyết nguyệt, mở con đường cổ dẫn sâu vào Hung sào. Trước ba cánh cửa đỏ sậm, Thạch Nghị chọn cửa thứ nhất, Tần Hạo kiên quyết đi cửa thứ hai, còn Thạch Hạo dẫn Lộ Dịch, Lạc Đạo và Lam Nhất Trần vào cửa thứ ba. Nhóm Thạch Hạo lần lượt vượt qua xích thần quy tắc, hắc hỏa, cổ thú do hình vẽ biến thành và nhiều hiểm họa đủ sức ngăn cản sơ đại. Giữa biển dung nham, họ hái được sáu, bảy thánh quả rồi dùng một quả đổi lấy sự trợ giúp của cốt giao để sang bờ đối diện. Sau hơn năm mươi cửa ải, tranh đá của Thạch Hạo phát sáng, xác nhận đoàn đã tiến vào đúng lộ tuyến dẫn tới tạo hóa riêng. Gần điểm cuối, họ tìm thấy bồ đoàn hỗn độn cùng nhiều hài cốt siêu phàm và nhận ra một thi hài là Bành Thiên Ý, quái thai cổ đại của Thần Dực tộc từng mất tích sau lần thứ hai tiến vào Tiên cổ. Phát hiện ấy khiến cả đoàn hiểu rằng nguy hiểm thực sự ở cuối tuyến đường có thể vượt xa toàn bộ những khảo nghiệm trước đó."},{"chuong":849,"tieuDe":"Kinh Văn Hiện Ra","tomTat":"Lam Nhất Trần kiểm tra di cốt Bành Thiên Ý và phát hiện nguyên thủy chân cốt của kỳ tài Thần Dực tộc đã bị người đến sau lấy mất. Khi cả nhóm dùng thần niệm dò xét, bồ đoàn truyền ra phần mở đầu của một cổ kinh xoay quanh đại đạo sức mạnh, nhưng đồng thời phát động lưỡi đao ánh sáng chuyên chém nguyên thần. Linh thân của Lộ Dịch và Lam Nhất Trần lần lượt bị diệt, khiến hai người đều chịu thương tổn. Lạc Đạo đề nghị rút lui nhưng con đường cũ đã bị bức tường không thể phá hủy phong kín, còn Đả Thần Thạch xác định bồ đoàn chính là trung tâm trận pháp. Thạch Hạo dùng chân thân ngộ pháp, để nguyên thần thi triển Luân Hồi thuật và Lôi Đế pháp giao chiến suốt một canh giờ rồi tiêu diệt lưỡi đao ánh sáng. Sau khi hắn hồi phục, bồ đoàn mở cửa truyền tống cả nhóm vào động phủ có một trăm cửa đá, trong đó mười cửa mang chữ Tử. Ở nơi sâu nhất, họ nhìn thấy một cổ động có bàn ngọc và cốt thư thần thánh đang tỏa tiên quang."},{"chuong":850,"tieuDe":"Tiên Động","tomTat":"Thạch Hạo cùng Lạc Đạo, Lam Nhất Trần và Lộ Dịch tới động phủ có gần hai trăm cao thủ tụ tập, rồi hắn tìm ra và đánh chết chàng trai áo đen đang kích động quần hùng hợp sức sát hại nhóm mình. Áp lực trên đường tới tiên động buộc Lộ Dịch quay lại, còn Lạc Đạo và Lam Nhất Trần phải dừng trên các đạo đài phía sau; Lam Nhất Trần dùng Lam huyết thử nghiệm và nghe được một câu kinh văn. Thạch Hạo tiếp tục vượt qua sức ép khủng khiếp, chiếm đạo đài thứ hai mươi mốt trong hàng ba mươi sáu đạo đài gần tiên động. Long Nữ vượt qua cửa Tử, nhẹ nhàng tiến tới đạo đài thứ hai mươi hai và để lộ thân phận quái thai cổ đại sống trong biển sâu. Hai mươi hai cao thủ hợp sức phá tan màn sáng hỗn độn và tiên quang, tiến vào nơi có bàn đá ngọc cao như núi cùng bảy tấm cốt thư thần thánh. Thần dược, túi càn khôn, pháp khí và cốt thư lập tức châm ngòi cho cuộc hỗn chiến, trong khi cấm chế của tiên động kéo những người đang bay trở lại mặt đất để bảo vệ động phủ. Giữa lúc đánh trả người phía sau, phù văn từ chưởng lực của Thạch Hạo vô tình đánh trúng Long Nữ đang bị nhiều cao thủ vây công."},{"chuong":851,"tieuDe":"Hung Sào Kinh Biến","tomTat":"Sau một va chạm khiến Long Nữ nổi giận, Thạch Hạo nhận ra nàng dường như có thể đọc được tâm niệm của mình và suy đoán nàng đã lĩnh ngộ Tha Tâm thông. Không muốn bỏ lỡ tạo hóa, hắn tránh cuộc giao thủ kéo dài rồi lao vào tranh đoạt cây cổ dược hoa bảy màu, nhưng thần dược tự nhổ rễ và biến mất trong vách đá không thể phá hủy. Thạch Hạo chuyển sang Ốc biển Thiên Văn, song kỳ bảo này cũng chui vào vách đá và mất dấu, khiến hắn bắt đầu cảnh giác với cách bố trí trong tiên động. Khi áp lực quanh các đạo đài biến mất, đông đảo cường giả tràn vào, còn một thanh niên tóc trắng dùng bí bảo Thiên Thần để tiếp cận bảo cốt trên bàn ngọc. Vừa chạm vào bảo cốt, người này bị nhóm xương trắng hút huyết dịch, đồng thời khí hỗn độn phóng ra kiếm khí tuyệt thế càn quét quần hùng. Thạch Hạo lập tức cảnh báo Lạc Đạo, Lam Nhất Trần và Lộ Dịch rút lui rồi chạy khỏi tiên động cùng Long Nữ. Nắp lò luyện đan giúp hắn tránh bị kiếm khí chém lìa, nhưng lực phản chấn vẫn khiến hắn thổ huyết, xương cốt gần như đứt đoạn và cơ thể bị đánh bay."},{"chuong":852,"tieuDe":"Một Khúc Sáo Tiễn Quần Hùng","tomTat":"Cốt thư trên bàn đá ngọc hút cạn bảo huyết của thanh niên tóc trắng, giết hắn rồi kích hoạt kiếm khí hỗn độn quét khắp động cổ. Thạch Hạo kịp cảnh báo Lam Nhất Trần và Lạc Đạo rời đạo đài, sau đó thu họ cùng Lộ Dịch vào đỉnh khi sát cục tiếp tục hút máu, ký hiệu và cốt văn của những người mắc kẹt. Giữa đường thoát đầy phù văn chết chóc, hắn lần theo dấu ấn của Tần Hạo, dùng lò luyện đan dẫn lôi đình phá vách trận pháp và tìm thấy người em bị thương trong chiến trường cổ. Tần Hạo cho biết hơn nghìn cao thủ đã chết trước đảo dược liệu, còn mình sống sót nhờ chiến y Trường Sinh và một bí bảo thế mạng. Sau một ngày một đêm chạy qua sát trận, Thạch Hạo, Long Nữ và Tần Hạo hội ngộ Thạch Nghị, rồi biết được Hung sào là âm mưu thu thần huyết cùng phù văn đã vận hành suốt sáu bảy đời. Họ gặp Trường Cung Diễn trước cánh cửa cổ và cùng sử dụng các bí bảo mạnh nhất để phá vòng vây, nhưng chỉ hơn mười người sống sót vượt qua. Khi nhóm người thoát lên mặt đất, một nam tử dung mạo hoàn mỹ đứng trên miệng Hung sào thổi sáo ngọc, dẫn vô số cánh hoa xuyên thủng những sinh linh đang chạy trốn và biến cổ địa thành biển máu."},{"chuong":853,"tieuDe":"Đêm Trăng Giết Quần Hùng","tomTat":"Dưới huyết nguyệt, một chàng trai bí ẩn đứng trên đoạn sơn thổi cốt địch, dùng cánh hoa phù văn tàn sát các cường giả trong Hung sào. Trường Cung Diễn bắn mũi tên đen truy kích nhưng đối phương liên tục né khỏi chân thân, sau đó còn gọi ra túi càn khôn có thể thu núi sông và luyện hóa thần linh. Theo tiếng sáo, hơn vạn Quỷ Ma thần tràn khỏi các hang động, khiến nhóm Thạch Hạo nhận ra toàn bộ khu vực đã bị chuẩn bị thành một sát cục. Long Nữ dùng sừng cổ khuấy loạn hư không, còn Trường Cung Diễn xác định một phần Hung sào cùng trận pháp đã nằm dưới sự điều khiển của kẻ bí ẩn nên cả nhóm buộc phải rút lui. Những manh mối từ di ngôn cổ đại cho thấy sát cục có thể đã được bố trí qua sáu, bảy đời, với hơn mười vạn sinh linh bị huyết tế để mở một khu vực hoặc ao tiên huyết bị phong kín. Long Nữ bác bỏ suy đoán rằng người thổi sáo là Thập Quan vương, khiến thân phận của kẻ chủ mưu càng thêm khó lường. Khi quần hùng chạy tới Vẫn Tiên lĩnh, Quỷ Ma thần chặn cả phía trước lẫn phía sau và giết chết nhiều cường giả, buộc Thạch Hạo phải ra tay toàn lực mới gian nan phá được vòng vây."},{"chuong":854,"tieuDe":"So Sánh Tiên Khí","tomTat":"Nhóm Thạch Hạo chạy khỏi Hung sào giữa lúc hơn một vạn Quỷ Ma thần truy sát các tu sĩ còn lại. Chàng trai bí ẩn đổi sang sử dụng Ốc biển Thiên Văn, phát thần âm giết gần sạch sinh linh trong vùng núi rồi triệu tập đại quân Hắc Thần trùng. Thạch Nghị, Long Nữ, Trường Cung Diễn, Thạch Hạo và Tần Hạo lần lượt vận dụng cổ bảo để mở đường nhưng vẫn nhanh chóng kiệt sức trước trùng triều áp đảo. Qua Trùng Đồng và nhận định của Long Nữ, cả nhóm xác nhận đối phương đã tu ra tiên khí, từ đó Thạch Nghị cùng Trường Cung Diễn quyết tâm khiêu chiến cửa ải vượt qua cổ nhân. Tần Hạo bị Hắc Thần trùng xuyên thủng thân thể, được Thạch Hạo cứu và thu vào đỉnh trước khi cả nhóm vượt khỏi quỷ lâm. Trùng triều dừng lại ở ranh giới cổ địa, còn người bí ẩn chủ động rời đi sau lời cáo biệt. Khi huyết quang và huyết dịch của hơn mười vạn sinh linh hội tụ về Hung sào, những người sống sót quyết định tới các thành trì dán chân dung đối phương để điều tra thân phận."},{"chuong":855,"tieuDe":"Con Đường Gian Nan","tomTat":"Sau khi rời Hung sào, Trường Cung Diễn nhận định chàng trai thần bí đã dùng máu và phù văn của hàng vạn sinh linh, bố trí qua nhiều đời để vun đắp đạo quả. Thạch Nghị rời đi bế quan, còn Tần Hạo chia tay Thạch Hạo để tự suy ngẫm con đường của mình. Thạch Hạo, Trường Cung Diễn và Long Nữ tới Vân giới, nơi Long Nữ huy động mạng lưới Long cung treo thưởng truy tìm lai lịch người bí ẩn. Qua cuộc bàn luận về con đường tu ra tiên khí, Thạch Hạo biết Thập Quan vương có nền móng từ một cây nhỏ hơn một kỷ nguyên tuổi, còn Ninh Xuyên đang tiến gần tới thành tựu tương tự. Nhận ra khoảng cách và nguy cơ bị đào thải, hắn quyết bước lên con đường khốc liệt này dù chỉ mới tích lũy một đời. Hai ngày sau, Thạch Hạo truyền hóa thuật đổi dung mạo cho Lộ Dịch, Lạc Đạo và Lam Nhất Trần, nhờ họ dò tìm thần dược rồi chia đường chuẩn bị bế quan. Hắn tới Quang Minh thành tìm cố nhân, nhưng chỉ biết một cô gái nghi là Thanh Y từng lưu lại đây nửa ngày trước khi rời đi."},{"chuong":856,"tieuDe":"Vườn Hoa Đào","tomTat":"Thạch Hạo lần theo dấu ấn Thanh Y để lại tại thành Quang Minh và đến thành Thanh Linh thuộc Thanh Linh giới. Trong một quán rượu giữa vườn hoa đào, hắn nghe các tu sĩ bàn về thảm án Sào giới, tổn thất chưa rõ của Ninh Xuyên và những lời đồn liên quan tới ba huynh đệ Thạch tộc. Sau khi hỏi mua thịt chim thần và mãnh thú, hắn biết sâu trong vườn đào có Bát Trân lâu nên lập tức tìm tới. Trước tửu lâu, chiến tướng thứ hai của Minh tộc xuất hiện từ một quan tài cổ màu đen, để lộ thân phận thần thi thượng cổ đã thông linh và từng giết hơn một sơ đại. Lên tầng cao nhất, Thạch Hạo gọi rượu thánh dược, Bát Trân Lý và Bát Trân Phượng, đồng thời nhận ra Thanh Y đang ngồi cùng một nhóm người Tiên điện. Nhóm này tuyên bố truyền nhân Tiên điện đã dung hợp chủ thân với thứ thân, treo thưởng truy tìm Hoang và dự định tự mình trấn áp hắn làm tôi tớ. Thạch Hạo liền yêu cầu họ mang thần dược cùng thánh dược tới đổi tin tức, đồng thời gọi truyền nhân Tiên điện đến gặp vì hắn biết Hoang đang ở đâu."},{"chuong":857,"tieuDe":"Tự Bán Mình","tomTat":"Thạch Hạo dùng diện mạo giả tiếp xúc với nhóm người của Tiên điện và tuyên bố biết chính xác tung tích Hoang, tức tung tích của chính mình. Hắn mặc cả tiền thưởng từ một trăm cây thánh dược và mười cây bán thần dược xuống còn bốn mươi cây thánh dược cùng tám cây bán thần dược. Chiến tướng thứ hai của Tiên điện ngoài mặt thương lượng nhưng bí mật dự định giao thuốc xong sẽ giết người báo tin, trong khi chiến tướng thứ hai của Minh tộc tới theo lệnh Hắc Ám thần tử và đề nghị gánh một nửa tiền thưởng để cùng truy sát Hoang. Sau khi hai thế lực gom đủ bảo dược, Thạch Hạo thu toàn bộ nhưng từ chối tiết lộ vị trí ngay, khẳng định chỉ trực tiếp nói với truyền nhân Tiên điện. Một sơ đại được phái đi mật báo, còn Thạch Hạo âm thầm thả Đả Thần Thạch xuống vườn hoa đào. Biết truyền nhân Tiên điện vừa treo thưởng giết mình vừa muốn bắt mình làm tôi tớ, Thạch Hạo quyết định chủ động bố trí phản kích."},{"chuong":858,"tieuDe":"Hoang Xuất Kích","tomTat":"Thạch Hạo tiếp tục che giấu thân phận trong lúc chờ truyền nhân Tiên điện, đồng thời dùng thánh dược lấy từ đối phương để thanh toán bát trân Lý và bát trân Phượng tại Bát Trân lâu. Thanh Y bất chấp sự chế nhạo của phe Tiên điện, sang ngồi cùng bàn và tranh ăn bát trân Phượng với hắn. Đả Thần Thạch trở về báo đã tìm được đường tới một nơi thần bí tại Thanh Linh giới, còn Thạch Hạo quyết định chấm dứt thế bị động và khôi phục uy danh Hoang. Khi nhóm Tiên điện và Minh tộc định bắt người, hắn công khai thân phận, dùng bảo thuật lôi đình giết ba cường giả rồi tiếp tục hạ cô gái sơ đại và thanh niên tóc đỏ. Kim Sí Đại Bàng hóa về bản thể giao chiến nhưng bị pháp môn Côn Bằng khắc chế và bị Thạch Hạo giết chết. Ở chiến trường bên kia, Thanh Y dùng Thanh Nguyệt diễm thiêu chiến tướng thứ hai cùng toàn bộ những người Minh tộc còn lại thành tro. Sau chiến thắng, Thạch Hạo giao xác Kim Sí Đại Bàng cho Bát Trân lâu chế biến và tuyên bố lên đường tìm giết truyền nhân Tiên điện."},{"chuong":859,"tieuDe":"Long Huyết Tổ Ngạc","tomTat":"Sau khi rời rừng đào, Thạch Hạo cùng Thanh Y chuyển sang chủ động truy tìm truyền nhân Tiên điện, khiến những người từng bị Hoang bán tin giả nhận ra mình đã mắc lừa. Đả Thần Thạch dẫn họ tới một đầm lầy ở Thanh Linh giới, nơi chiến tướng thứ ba của Tiên điện canh giữ tế đàn truyền cốt thư. Thạch Hạo dùng thân pháp áp sát, triển khai động thiên duy nhất giam cầm đối phương rồi dùng Bảo thuật Lôi Đế đánh chết hắn khi hắn định phá tế đàn. Đả Thần Thạch phá giải trận pháp, suy diễn tọa độ và mở thông đạo màu bạc đưa cả nhóm tới một tiểu thiên thế giới phủ đầy cát vàng. Sau khi tìm thấy đảo xanh cùng động cổ hỗn độn, Thạch Hạo đột kích nhưng chạm trán Long Huyết tổ ngạc, chiến tướng thứ nhất của truyền nhân Tiên điện. Dị chủng mang máu rồng thi triển Nhân Tiên ấn và đối công hơn một trăm chiêu, song cuối cùng bị sức mạnh Côn Bằng đánh cho thân thể rạn vỡ rồi nổ tung. Hạ xong chiến tướng thứ nhất, Thạch Hạo hướng vào sâu trong động cổ gọi truyền nhân Tiên điện ra giao chiến."},{"chuong":860,"tieuDe":"Mở Thiên Nhãn","tomTat":"Sau khi giết Long Huyết tổ ngạc, Thạch Hạo xác định động cổ trên đảo chỉ là một trạm trung chuyển gần nơi truyền nhân Tiên điện bế quan. Đả Thần Thạch phá giải trận pháp, mở ra kho chứa lượng lớn thần liệu, thánh dược và bán thần dược do các cứ điểm thu gom. Thanh Y nhận ra Vật liệu mật đá, còn Thạch Hạo dùng trùng đồng tìm được tảng đá chứa mật tiên. Hắn dùng hơn nửa mật vàng gột rửa đôi mắt và chính thức mở Võ đạo Thiên nhãn giai đoạn đầu, có thể nhìn xuyên vật thể, thấy xa, nhận biết bản chất, nhìn thấu hư ảo và quan sát quỹ tích vận động. Thanh Y giữ phần mật đá còn lại để chờ thời điểm thích hợp sử dụng, rồi dùng đại thần thông cùng Thanh Nguyệt diễm ngăn Thạch Hạo thử nhìn xuyên cơ thể nàng. Cả nhóm lấy sạch kho báu của truyền nhân Tiên điện trước khi Đả Thần Thạch nghiên cứu tế đàn dẫn tới bí cảnh kế tiếp. Thạch Hạo điều tức tới trạng thái cao nhất, chuẩn bị tiếp tục truy tìm đối thủ với thần giác đã trở nên nhạy bén hơn."},{"chuong":861,"tieuDe":"Vạn Độc Thần Thụ","tomTat":"Đả Thần Thạch nghiên cứu tế đàn màu vàng của Tiên điện và nhận ra trận văn trên đó mang biến hóa phù văn Nhân Tiên, đồng thời có nét tương tự đại trận Liễu Thần từng bố trí tại Thạch Thôn. Vì chưa nhìn thấu toàn bộ nguy cơ, nó thu tế đàn làm chiến lợi phẩm rồi tự dựng một truyền tống trận màu xanh để đưa Thạch Hạo và Thanh Y tới gần nơi truyền nhân Tiên điện bế quan. Cả nhóm tiến vào sơn mạch đầy khói độc và thần trùng, phải dùng chiến kích Hư Không để tránh những khu vực quá nguy hiểm. Nhờ Võ đạo Thiên nhãn và chỉ dẫn của Thanh Y, họ phát hiện Vạn Độc Thần Thụ cùng nhiều độc trùng Chân Thần và các Thiên Thần đã chết hoặc gần như tử vong quanh gốc. Thanh Y tiết lộ quả chín của thần thụ có thể giúp sinh linh chịu nổi kịch độc lập tức trở thành Thiên Thần mang độc, nhưng những quả hiện có vẫn còn non. Đả Thần Thạch sau đó tìm thấy trận pháp cùng cánh cửa dẫn vào vùng đất cổ dưới thần thụ, xác nhận đây là nơi truyền nhân Tiên điện đang bế quan. Thạch Hạo quyết định lẻn vào quấy nhiễu đối thủ để đáp trả việc hắn treo thưởng lấy mạng mình."},{"chuong":862,"tieuDe":"Liệt Nửa Người","tomTat":"Trận pháp dưới Vạn Độc Thần Thụ phong tỏa hư không, còn độc quang ăn mòn thần lực và đạo hạnh, khiến nhóm Thạch Hạo không thể cưỡng ép vượt qua bằng những phương thức thông thường. Thạch Hạo cất Thanh Y cùng Đả Thần Thạch vào túi càn khôn, ẩn trong lò luyện đan cổ rồi dựa vào sức phòng ngự của nó xông qua vòng độc quang. Nhờ kinh nghiệm quan sát Liễu Thần bố trí trận pháp, Đả Thần Thạch dẫn cả nhóm xuyên qua cổ trận và tiến vào một tiểu thiên địa như tiên cảnh. Tại rừng trúc tía, họ phát hiện Đế Trùng đang ngộ đạo trên Ngộ Đạo thạch, chung quanh có máu Tiên, cốt thư cảm ngộ cùng nhiều tài nguyên quý do Tiên điện chuẩn bị. Thanh Y truyền Long Ngâm cho Thạch Hạo rồi tự thi triển Phượng Minh, phối hợp với lò luyện đan và sát trận của Đả Thần Thạch để quấy nhiễu đối phương đúng thời khắc then chốt. Máu Tiên trong cơ thể Đế Trùng mất kiểm soát, làm nửa người hắn rách nát và buộc hắn thu vội những vật liệu có thể mang theo rồi chạy vào truyền tống trận. Vì không thể thu nổi Ngộ Đạo thạch, hắn phải bỏ lại kỳ thạch cùng nhiều tài nguyên và còn tức giận đến phun máu khi nghe Thạch Hạo lên tiếng cảm ơn."},{"chuong":863,"tieuDe":"Bất Diệt","tomTat":"Kế nghi binh của Thạch Hạo, Đả Thần Thạch và Thanh Y khiến Đế Trùng tưởng cổ trận đã bị phá, chịu phản phệ rồi vội vã bỏ chạy. Trong lúc ngoại giới xôn xao vì thất bại của truyền nhân Tiên điện, Sinh linh Bất diệt triển khai hình chiếu từ khu không người, công khai bảo vệ Hoang và đối đầu tồn tại cổ xưa trong điện đồng. Đế Trùng ép phần tiên huyết chưa dung hợp khỏi cơ thể, phong ấn nó rồi dùng thần đan chữa lành thương thế. Đả Thần Thạch phá được một góc cổ trận, giúp Thạch Hạo tiến vào khu ngộ đạo và dùng lò luyện đan thu Ngộ đạo thạch mà pháp khí cấp thần không thể chứa nổi. Thạch Hạo cùng Thanh Y tiếp tục lấy cốt thư và những vật quý còn lại trước khi trở về Thanh Linh giới. Sau khi phát hiện cơ duyên bị vét sạch, Đế Trùng tới thành Quang Minh thách đấu rồi lần theo tin tức truy đến Thanh Linh giới. Chương kết thúc khi Thạch Hạo bay lên nghênh chiến đối thủ."},{"chuong":864,"tieuDe":"Chí Tôn Huyết Hồi Phục","tomTat":"Đả Thần Thạch chen vào trận quyết đấu, tiết lộ rằng mật đá lấy từ nơi bí ẩn của Đế Trùng đã giúp Thạch Hạo mở Võ đạo thiên nhãn, khiến đối phương nổi giận. Đế Trùng hóa thành Cửu đầu điểu, thi triển Cửu đầu bất tử thân phân hóa chín Ma thần, nhưng Thạch Hạo dùng Ba đầu sáu tay, lôi đình và Miễn dịch pháp lực để phá giải. Hai người tiếp tục giằng co bằng Nhân tiên ấn, Thượng Thương chi thủ, tán thủ Chân Hoàng, Tiên vương cửu phong cùng nhiều biến hóa Côn Bằng và lôi điện. Khi toàn bộ tiềm năng được mở ra, Chí Tôn huyết phân tán trong cơ thể Thạch Hạo đồng loạt hồi phục, khiến Thượng Thương chi thủ và phù văn Luân Hồi trở nên hoàn chỉnh. Đế Trùng thiêu đốt tiềm năng tạo ra tiên vụ mơ hồ nhưng vẫn bị một chưởng xuyên thủng bảo thuật và đánh tan sương mù Tiên đạo. Thạch Hạo sau đó liên tiếp đánh gãy nhiều xương và gần như nghiền nát nửa người đối thủ, giành ưu thế áp đảo trong trận chiến."},{"chuong":865,"tieuDe":"Tiên Điện Chết Yểu","tomTat":"Đế Trùng dùng huyết mạch Cửu Đầu Điểu và Cửu diệt bất tử để tái tạo thân thể sau khi bị Thượng Thương chi thủ cùng phù văn Luân Hồi đánh trọng thương. Hắn mặc chiến giáp Tiên vũ, thiêu đốt tiềm năng rồi phóng thích nguyền rủa gỉ đồng xanh, nhưng Thạch Hạo dùng Chí tôn huyết và các bảo thuật phá giải toàn bộ thủ đoạn. Sau nhiều lần tái sinh với cái giá ngày càng lớn, Đế Trùng bị Thạch Hạo giết chết vĩnh viễn tại Thanh Linh giới. Thạch Hạo kiểm tra thi thể, thu nhiều vật chất thần thánh và một bình ngọc phong ấn tiên huyết. Một sát thủ Thiên quốc đánh lén hắn nhưng bị truy vào hư không và chém đầu, còn cao thủ cấp thần đi cùng tự sát khi bị Tào Vũ Sinh, Thái Âm Ngọc Thỏ và Thanh Y khóa kín đường chạy. Sau trận chiến, Thạch Hạo mời mọi người dự tiệc Kim Sí Đại Bàng tại Bát Trân lâu và vui đùa với Thái Âm Ngọc Thỏ."},{"chuong":866,"tieuDe":"Bạn Đường","tomTat":"Thạch Hạo trao một cây thánh dược cho Thái Âm Ngọc Thỏ rồi thiêu thân thể còn lại của Đế Trùng thành tro, khiến truyền nhân Tiên điện chính thức hình thần đều diệt sau năm lần bị giết. Cái chết này làm ngoại giới chấn động, khiến uy danh Tiên điện tổn hại nặng và khiến lão điện chủ trong cổ điện hỗn độn bộc phát sát ý. Tại Bát Trân lâu ở Thanh Linh giới, Thạch Hạo, Thanh Y, Tào Vũ Sinh và Thái Âm Ngọc Thỏ dự yến thịt Kim sí đại bàng cùng thánh tửu. Trong lúc trò chuyện, Thạch Hạo tuyên bố sẽ bế quan tu ra tiên khí, Tào Vũ Sinh trình bày con đường thai nghén đại trận có sinh mệnh, còn Thái Âm Ngọc Thỏ nói về việc cảm ngộ tinh hoa cây cỏ để hình thành thần thể tự nhiên. Thanh Y cảnh báo rằng Liệp Sát giả Thiên quốc có thể đã nhận thù lao để nhằm vào Thạch Hạo. Cả nhóm quyết định cùng trở lại nơi giao giữa ba ngàn con đường đá và hỗ trợ nhau tu hành. Dù Thạch Hạo cảnh báo hiện tượng không rõ từng khiến mình lâm nguy, Đả Thần Thạch và Tào Vũ Sinh vẫn đề nghị bố trí trận pháp để bắt sống nó, cuối cùng khiến hắn đồng ý tham gia kế hoạch."},{"chuong":867,"tieuDe":"Lại Xuất Hiện","tomTat":"Đả Thần Thạch cùng các đồng bạn dùng lượng lớn thần liệu dựng hàng chục sát trận quanh ba ngàn con đường đá, chuẩn bị cho Thạch Hạo bế quan luyện chân ngã. Ngồi trên Ngộ Đạo thạch, Thạch Hạo lần lượt dẫn tới hai nghìn một trăm luồng ánh lửa đại đạo vào thân, nhiều lần bị nung tới trọng thương và phải dùng Bán Thần quả cùng thánh dược hồi phục. Sau lần rèn luyện này, một chiếc đèn cổ mang điềm xấu xuyên qua sát trận và lần lượt dẫn tới hai sinh linh sương xám có sức chiến đấu tương đương hắn. Sự can thiệp bằng sức mạnh Thái Âm của Thái Âm Ngọc Thỏ khiến quy tắc kỳ lạ sinh thêm công kích nhằm vào Thạch Hạo, buộc các đồng bạn phải ngừng trợ giúp. Bị hai đối thủ giáp công tới gần chết, Thạch Hạo thúc đẩy hai loại phù văn trời sinh quấn chặt, cộng hưởng và dần quy nhất với Chí tôn huyết. Sức mạnh mới giúp hắn giết cả hai sinh linh, đồng thời làm một luồng tiên khí mơ hồ xuất hiện ngoài thân. Sống sót qua tai nạn, Thạch Hạo quyết định tiếp tục tiến tới mục tiêu dùng đủ ba nghìn ánh lửa đại đạo để đốt luyện chân ngã."},{"chuong":868,"tieuDe":"Tiên Khí","tomTat":"Sau khi hai sinh linh mặc giáp đồng bị đánh bại, chúng phát ra những lời cảnh báo rời rạc về con đường đã đứt rồi cùng giáp trụ và binh khí hóa thành bột phấn vì sự bào mòn của năm tháng. Thanh Y dùng Thanh Nguyệt diễm truy theo dấu vết, làm lộ một khe lớn bên ngoài ba ngàn con đường đá và xác định chúng tới từ hư không. Thạch Hạo nhận thấy tiên khí mơ hồ xuất hiện quanh thân, nhưng Tào Vũ Sinh và Thanh Y cảnh báo trạng thái này báo hiệu con đường riêng của hắn quá nguy hiểm, có thể dẫn tới hình thần câu diệt. Bất chấp lời khuyên, hắn quyết tiếp tục vì muốn tu thành nhiều luồng tiên khí và cần đủ sức đối phó Ninh Xuyên cùng chàng trai thần bí trong Hung sào. Thạch Hạo dùng Ngộ Đạo thạch bế quan, lấy thiên địa làm lò và đại đạo làm lửa, liên tục tăng số ánh lửa dùng để nung luyện chân ngã. Hắn nhiều lần bị thiêu hủy huyết nhục, xương cốt và nguyên thần, song Chí tôn dịch cùng các bảo dược giúp duy trì tính mạng. Khi dẫn động tới hai ngàn chín trăm luồng ánh lửa, Thạch Hạo cuối cùng ngưng tụ thành công luồng tiên khí trắng tinh đầu tiên quanh thân."},{"chuong":869,"tieuDe":"Tiên Khí Tẩm Bổ Thân Thể","tomTat":"Thạch Hạo tu thành một luồng tiên khí, khiến Thái Âm Ngọc Thỏ, Tào Vũ Sinh và Thanh Y vui mừng, nhưng thân thể hắn đã bị thiêu đốt đến mức gần cạn sạch sinh cơ. Khi chiếc đèn cổ và nhiều bóng mờ ngang sức hắn tiến đến trong sương xám, Thạch Hạo nuốt Bán Tham quả rồi quyết định ở lại nghênh chiến dù biết mình đang rơi vào tử cục. Luồng tiên khí bất ngờ phân tán, bị huyết dịch kéo vào cơ thể và dung hợp với Chí tôn huyết, khiến sát kiếp tưởng hắn đã thất bại nên rút vào vết rách hư không. Tào Vũ Sinh kể lại ghi chép trên một chiếc đỉnh tàn về kỳ tài từng được tiên khí cứu mạng nhưng không thể tu lại, sau đó bị một nhân vật vô thượng bắt đi nghiên cứu và chết. Thạch Hạo nhận ra mình khác tiền lệ ấy vì mới đốt hai ngàn chín trăm luồng ánh lửa phù văn, nghĩa là con đường tu luyện vẫn chưa hoàn tất. Sau thời gian dưỡng thương và suy ngẫm trên Ngộ Đạo thạch, hắn dùng Võ đạo Thiên nhãn phát hiện dị tượng ẩn trong cơ thể và tin rằng đó là chỗ dựa để tiếp tục siêu thoát."},{"chuong":870,"tieuDe":"Phía Cuối Ba Ngàn Con Đường","tomTat":"Thạch Hạo dùng Võ đạo Thiên nhãn phát hiện một ngọn lửa cấu thành từ ký hiệu đang ngủ sâu trong huyết nhục, nhưng nhiều ngày thử liên kết vẫn không thể đánh thức hoặc điều khiển nó. Thanh Y dùng một tia Thanh Nguyệt diễm thăm dò, song tia lửa tự động lùi lại khi tới gần mục tiêu và thoát khỏi sự khống chế của nàng. Trong thời gian bế quan, Thạch Hạo còn chứng kiến phù văn Chí Tôn thứ ba bắt đầu nảy mầm, từ đó lập chí tương lai sẽ khai sáng một hệ thống tu hành mới và lập tức bị lôi điện dị thường đánh trọng thương. Sau một tháng ngộ đạo, hắn bước vào ba ngàn con đường đá, chịu đựng ba ngàn đạo hỏa mà không dùng Bán Tham quả và thành công khiến một luồng tiên khí như chân long hiện ra quanh người. Dao động của lần vượt ải lan tới nhiều tiểu thiên thế giới dù Đả Thần Thạch đã bố trí trận pháp ngăn cách. Khi Thạch Hạo đang khôi phục, khí đen cùng đèn cổ áp sát và bốn sinh linh mang các dị tượng liên quan đến Côn Bằng, Lôi Đế, Thượng Thương kiếp quang cùng Luân hồi lần lượt xuất hiện. Trước những đối thủ mạnh mẽ ấy, Thạch Hạo quyết định chủ động chém sạch để tiếp tục truy tìm lời giải cho hiện tượng bí ẩn."},{"chuong":871,"tieuDe":"Trấn Áp","tomTat":"Giữa làn khói đen bao phủ ba ngàn đường cổ, bốn hình thể do các áo nghĩa cực hạn diễn biến cùng xuất hiện và vây đánh Thạch Hạo. Thanh Y, Tào Vũ Sinh, Thái Âm Ngọc Thỏ và Đả Thần Thạch không thể can thiệp, chỉ có thể lui lại theo dõi. Thạch Hạo tay không nghênh chiến, lần lượt đối kháng sức mạnh Côn Bằng, Lôi Đế, Luân hồi và Thượng Thương chi thủ, đồng thời nhận ra những đối thủ này không phải sinh linh thật. Trong lúc bị vây công, hắn trúng một chưởng vào lưng rồi bị biển lôi điện bao phủ, nhưng vẫn duy trì thế giằng co nhờ đạo hạnh tăng mạnh sau quá trình đốt ba ngàn ngọn lửa. Trước tình thế nguy cấp, hắn làm Chí Tôn huyết sôi trào và giải phóng luồng phù văn thứ ba từng bị chính mình phong ấn. Sức mạnh chưa từng được các hình thể áo nghĩa diễn hóa tạo ra thánh quang chém lìa đầu kẻ nắm giữ Luân hồi. Thạch Hạo lập tức chuyển sang phản công và dốc toàn lực tiến lên nhằm trấn áp ba đối thủ còn lại."},{"chuong":872,"tieuDe":"Thành Công","tomTat":"Thạch Hạo trực diện chống lại Lôi động cửu thiên, dùng Võ đạo Thiên nhãn nhìn thấu quỹ tích đối thủ rồi dung hợp ba loại thần văn để lần lượt tiêu diệt bốn sinh linh. Hắn nhận ra Chí Tôn thuật thứ ba mới mở phong ấn có thể kết hợp với Luân hồi và Thượng Thương, dù bản thân thuật vẫn chưa định hình hoàn chỉnh. Huyết nhục của bốn sinh linh sau đó tái hợp thành một cá thể mới sở hữu toàn bộ năng lực trước đó, kể cả Chí Tôn thuật vừa được Thạch Hạo bộc lộ. Sau hàng trăm lần giao phong, Thạch Hạo giết được sinh linh tổng hợp và dùng đạo hỏa ba ngàn hoa văn thiêu sạch dấu vết. Chiếc đèn cổ ghi lại trận quyết chiến rồi bỏ trốn, nhưng khi soi tới ngọn lửa thần bí trong cơ thể Thạch Hạo, nó khiến ngọn lửa thức tỉnh, lao ra phá đèn thành bột và đốt sạch khói đen. Cuối cùng, Thạch Hạo phát hiện một vết nứt hư không khổng lồ, nhìn thấy cảnh tượng khiến hắn liên tưởng tới một truyền thuyết đáng sợ và khẩn cấp ngăn Thanh Y, Tào Vũ Sinh cùng những người phía sau tiếp cận."},{"chuong":873,"tieuDe":"Nơi Khởi Nguồn","tomTat":"Trên đường truy tìm nơi khởi nguồn, Thạch Hạo nhìn thấy một cổ thuyền màu đen nhuốm máu trôi trong vết rách hư không và nhận ra đây là một trong ba tai họa từng được Ma huyết quỷ thần thụ cảnh báo. Hắn yêu cầu Thanh Y, Tào Vũ Sinh cùng những người khác rút xa, nhưng bản thân lại bị sức hút áp đảo kéo lên boong và không thể bay khỏi thuyền. Khi dùng Võ đạo Thiên nhãn và cốt văn thăm dò các vũng máu đỏ sậm, hắn bị phù văn trong cổ huyết phản chấn, đồng thời phát hiện một bộ xương cho thấy người từng định lấy máu đã chết thảm. Đi sâu vào boong thuyền, Thạch Hạo nhận ra nhiều lỗ kiếm cùng dấu tích của một trận đại chiến kinh thiên, khiến chùm lửa thần bí trong cơ thể hắn tự hiện ra chiếu rọi. Hắn tiếp tục bắt gặp những vại lớn như núi chứa nhiều loại máu có phù văn đủ sức xóa bỏ thần linh. Cuối chặng thăm dò, Thạch Hạo tìm thấy một đoạn sừng trong suốt dính máu, có hình dáng gần giống sừng hươu hoặc một đoạn sừng Chân Long, nhưng vẫn chưa xác định được nguồn gốc hay cách rời khỏi cổ thuyền."},{"chuong":874,"tieuDe":"Đáng Sợ","tomTat":"Thạch Hạo phát hiện một chiếc sừng rồng nhuốm máu nhưng không thể tiếp cận vì phù văn và khí tức nguy hiểm, sau đó được ngọn lửa thần bí trợ giúp hóa giải sát khí trên một chiếc vảy rồng vàng mang ký hiệu giống chữ “Nghịch”. Hắn thu lấy chiếc vảy nặng khoảng mười vạn cân rồi đi sâu hơn mười ngàn dặm trên cổ thuyền và bước lên một tế đàn đen có ao huyết dịch năm màu. Huyết dịch tái hiện chiến trường Biên hoang, nơi bảy vị Vương trọng thương cùng cư dân thành lớn kiên quyết chống địch, khiến Thạch Hạo nhận ra dấu ấn bị gọi là chữ “Tội” thực chất là vinh quang của tổ tiên. Một Vương giả ngã xuống, sáu người còn lại nhắc tới thiên địa bị phong tỏa, viện quân và Minh ước, còn hình ảnh cuối cho thấy chính cổ thuyền màu đen từng mang máu vượt qua Biên hoang rồi tiến vào vết rách hư không. Không tìm được đường rời đi, Thạch Hạo quyết định tiếp tục khám phá khoang thuyền rộng như một thế giới. Tại đây, hắn nhìn thấy núi gãy, vô số thi hài cổ xưa và một đỉnh đá bị phong ấn nhưng đầy vết nứt. Cảnh bàn ngọc với bài vị Đại Xích thiên chủ, Thanh Vi thiên chủ, Vũ Dư thiên chủ cùng những đầu lâu đẫm máu thoáng xuất hiện rồi biến mất, để lại nghi vấn về thứ đang bị phong kín trong đỉnh."},{"chuong":875,"tieuDe":"Phần Cuối","tomTat":"Thạch Hạo tiến sâu vào cổ địa trong cổ thuyền, nhìn thấy những bài vị, danh xưng và đầu lâu dính máu bị phong ấn trong một chiếc đỉnh. Trên đường vượt qua chiến trường cổ đầy thi hài và binh khí mục nát, hắn dùng Chiến kích Hư không giết một xác ướp bất ngờ tập kích. Hắn nhận ra chiếc đỉnh được chế tạo nguyên khối từ Thế Giới thạch nhưng đã đầy vết nứt, để nhiều luồng khí kỳ dị rò ra ngoài. Một ý chí tà dị từ trong đỉnh hứa ban bất diệt và trường sinh, cưỡng ép hắn tiến tới mở phong ấn, song hắn kịp tỉnh táo và thoát khỏi sự mê hoặc. Ngọn lửa thần bí trong cơ thể hắn sau đó tự hóa thành gương cổ, phản chiếu cảnh vật và dấu tích chiến đấu quanh thạch đỉnh trước khi quay về. Đi tới cuối cổ địa, Thạch Hạo phát hiện một vực sâu vô biên và dùng Thiên mục nhìn thấy thi thể một Vương giả trấn thủ Biên hoang đang ngồi trên cửa vực để duy trì phong ấn. Tàn niệm cho biết vị Vương giả đã trọng thương trở về từ Biên hoang, truy đuổi một thứ chưa rõ rồi dùng thân trấn áp nó tới chết, khiến Thạch Hạo đau buồn vì công tích ấy bị lãng quên trong khi hậu duệ của ông lại mang danh hậu nhân tội huyết."},{"chuong":876,"tieuDe":"Chữ Tội Được Tăng Thêm","tomTat":"Trước thi thể vị Vương đã chết khi lấy thân trấn giữ vực sâu, Thạch Hạo đau xót cho những người từng đẫm máu bảo vệ Biên hoang nhưng có hậu duệ bị gọi là tội huyết, rồi thề tương lai sẽ tới đó tham chiến. Chữ Tội trên xương trán vị Vương cộng hưởng và dung nhập vào hoa văn trên mi tâm Thạch Hạo, khiến huyết dịch hắn sôi trào, giúp hắn thích nghi với tuyệt địa và vận dụng lại cốt văn mà không bị sức mạnh cấm kỵ cắn trả. Trong lúc phong ấn vực sâu suy yếu và khói đen bắt đầu thoát ra, hàng ngàn hàng vạn xác cổ cùng nhiều nhân kiệt thuộc các thời đại tràn khỏi dãy núi đen. Một nhóm chí tôn trẻ tuổi Thần Hỏa đại viên mãn hợp lực vây đánh, phá sụp động thiên duy nhất và khiến Thạch Hạo chịu thương tích gần chết. Người cầm kiếm thai màu xám chém đứt đôi đại kích của hắn, còn sinh linh mình người đầu kiến suýt đâm thủng tim hắn. Thạch Hạo cuối cùng đánh bay người cầm kiếm, đoạt kiếm thai rồi gia trì bảo thuật để chém chết hai đối thủ. Khi một nguồn sức mạnh không rõ lai lịch từ dưới vực sâu nghiền ép hắn, thi thể vị Vương lại phát sáng và truyền tới một luồng sức mạnh nhu hòa bảo vệ hắn."},{"chuong":877,"tieuDe":"Thoát Vây","tomTat":"Thi thể của Vương giả trấn thủ Biên hoang phát ra thần lực và phù văn còn sót lại, phá tan cuộc vây giết của các cường giả bị khí đen điều động quanh vực sâu. Chữ Tội trên mi tâm vị Vương bùng cháy mở đường, còn ngọn lửa thần bí trong cơ thể Thạch Hạo thiêu hủy đèn cổ, sương mù và những vết đen trên thi thể rồi đưa hắn thoát khỏi thuyền cổ. Trước khi cổ thuyền trôi sâu vào hư không, Thạch Hạo cảm nhận tàn niệm cầu viện và hứa sẽ đến Biên hoang, đồng thời quay lại giải quyết mọi chuyện. Xung đột giữa quy tắc kỳ lạ và phù văn bảo hộ khiến thân thể hắn nứt vỡ, một cánh tay đứt lìa, nhưng hắn dùng Bán thần quả cùng cốt văn để ổn định thương thế và nối lại tay. Tiên kiếm Đại La phát ra mưa ánh sáng, chém mở hư không đã khép và đưa hắn trở lại ba ngàn đường đá. Thanh Y, Tào Vũ Sinh, Thái Âm Ngọc Thỏ và Đả Thần Thạch vừa đón được hắn thì nhóm do các Liệp sát giả Thiên quốc dẫn đầu lập tức phục kích. Dù vẫn trọng thương, Thạch Hạo dùng kiếm thai giết sáu người rồi điều khiển cánh tay đứt bằng một tia tiên khí để tiêu diệt kẻ cuối cùng."},{"chuong":878,"tieuDe":"Tiên Kiếm Đại La","tomTat":"Cánh tay bị chém rời của Thạch Hạo vẫn phát huy uy lực đáng sợ, giết một cường giả rồi phối hợp với bản thể phá tan đợt ám sát bằng Hóa huyết thần châm. Hắn khống chế thần châm đánh ngược, giết Liệp sát giả màu bạc hai đầu bốn tay, sau đó cùng Tào Vũ Sinh, Thanh Y, Đả Thần Thạch và Thái Âm Ngọc Thỏ tiêu diệt toàn bộ những người mang sát ý. Trở lại ba ngàn đường đá, Thạch Hạo dùng Bán tham quả chữa thương và nhận ra tia tiên khí có thể dẫn tinh khí trời đất nuôi dưỡng thân thể, nguyên thần cũng như duy trì pháp lực. Tuy thương thế bên ngoài đã ổn định, một tia bí lực của pháp tắc kỳ lạ vẫn còn trong cơ thể, còn ngọn lửa thần bí đủ sức phá hủy nó lại không ra tay. Hư Thiên thần đằng nhận ra kiếm thai của Thạch Hạo chính là Tiên kiếm Đại La, phôi kiếm trời sinh bằng tiên kim Đại La từng thuộc về Ngũ Quan vương. Mọi người cũng biết Ngũ Quan vương từng xưng hùng năm đời nhưng gặp nạn khi bước ra bước quan trọng, bị khói xám mang đi và để lại thi thể cầm kiếm trên thuyền cổ màu đen."},{"chuong":879,"tieuDe":"Mù Mịt Và Rối Loạn","tomTat":"Thái Âm Ngọc Thỏ thử cầm Tiên kiếm Đại La và kích hoạt dị tượng phi tiên, cho thấy kiếm thai nặng hơn mười vạn cân này có tiềm năng trở thành chí bảo vô thượng. Thạch Hạo kể lại những bí ẩn trên cổ thuyền màu đen, khiến cả nhóm suy đoán một vị Vương trở về từ Biên hoang đã hy sinh để phong ấn tồn tại kỳ lạ dưới vực sâu. Từ số phận của các vị Vương, họ nhận ra nếu Biên hoang bị phá thì chiến tranh sẽ bao phủ ba ngàn châu và thượng giới. Tào Vũ Sinh chuyển lời sư phụ rằng chiến cuộc còn liên quan đến bất hủ, Đế, Tiên cùng nhiều phe có chỗ dựa đối lập. Hắn cũng tiết lộ quẻ bói kỳ lạ cho rằng Thạch Hạo không thuộc lịch sử này, đồng thời kể dự báo về một người vượt ngoài thời đại sẽ tới ba ngàn châu cầu viện. Lời tiên đoán còn cho biết Tào Vũ Sinh mang số mệnh bị chôn, nhưng hắn tin mình sẽ tỉnh dậy và bò ra khỏi lòng đất. Sau nửa năm bế quan, Thạch Hạo tuyên bố đã chuẩn bị tu luồng tiên khí thứ hai, song đồng ý ra ngoài củng cố đạo cơ trước. Tào Vũ Sinh sau đó đề nghị dẫn cả nhóm tới vùng cơ duyên nơi Ninh Xuyên từng đoạt xương tay còn sức sống và Thập Quan vương từng lấy được cây non Tiên đạo."},{"chuong":880,"tieuDe":"San Bằng Tất Cả","tomTat":"Từ tin tức của Long Nữ, nhóm Thạch Hạo biết cây nhỏ của Thập Quan vương và đồ vật thành Đạo của Ninh Xuyên đều bắt nguồn từ một địa phương cổ trong Tiên cổ nên quyết định lên đường tìm kiếm. Sau nửa năm bế quan, Thạch Hạo đã tu thành một tia tiên khí, thu nó vào máu thịt rồi tái xuất trước sự quan sát của ngoại giới. Hắn lần lượt đánh bại cường giả Ma Quỳ viên, sinh linh Hỏa Vân động và đệ tử của nhiều đạo thống thù địch, khiến những người theo dõi vừa tức giận vừa kiêng sợ. Trên đường đi, Hoàng điệp phá vỡ kén vàng, mọc đôi cánh thần lực trong suốt và chính thức hóa thành hồ điệp. Tào Vũ Sinh dùng cốt khí che thiên cơ để giấu hành tung của cả nhóm trước khi dẫn họ tiến vào Táng giới. Tại núi Đoạn Thiên, Thạch Hạo cảm nhận khí tức Tiên đạo đang bồi bổ tia tiên khí của mình, đồng thời nhận ra một dấu vết phảng phất như thuộc về Liễu Thần."},{"chuong":881,"tieuDe":"Táng Giới","tomTat":"Nhóm Thạch Hạo tiến vào Táng giới và mỗi người sinh ra một cảm ứng khác nhau trước dấu vết Tiên đạo, khiến Thạch Hạo nghi ngờ Liễu Thần có thể liên quan đến nơi này. Tào Vũ Sinh giải thích đây là chiến trường của kỷ nguyên trước, dưới lòng đất chôn giấu vô số sinh linh, di vật và bí mật, đồng thời chỉ ra những vùng sát cơ xen lẫn những miền tràn đầy sức sống. Khi gặp một bộ lạc Nhân Mã tộc mang huyết thống Tiên cổ đã biến dị, cả nhóm liên tưởng tới nguy cơ kỷ nguyên hiện tại bị hủy diệt nếu Biên hoang thất thủ. Tại rừng đá đỏ, họ biết Ninh Xuyên từng lấy được một xương tay còn sức sống chứa phù văn Tiên đạo hoàn chỉnh, còn một khối kim loại mới khai quật chỉ là đồng bảy màu chứ không phải tiên kim. Sau hai ngày di chuyển, nhóm đến hố trời có đất đá nhiễm máu, cứng chắc và ngăn cản thần thức. Võ đạo Thiên nhãn của Thạch Hạo nhìn xuyên lòng đất, phát hiện một nhà đá có phù văn sức sống rực rỡ, gợi khả năng vẫn còn vật sống từ Tiên cổ. Trái với đề nghị giữ kín của Thanh Y, Thạch Hạo muốn Minh tộc, Thiên quốc, Hỏa Vân động và Ninh Xuyên biết về phát hiện này."},{"chuong":882,"tieuDe":"Tiên Thể","tomTat":"Tào Vũ Sinh cảnh báo rằng cơ duyên trong Táng giới có thể thu hút quái thai cổ đại, còn Thạch Hạo dùng Tiên kiếm Đại La đào sâu dưới hố trời và tìm thấy một thạch điện từ kỷ nguyên trước. Sau khi phá mở điện đá, hắn phát hiện di thể một sinh linh Tiên cổ nhưng thận trọng rút lui, trong khi những người định chiếm lấy di thể bị sức phản chấn chấn thành thịt nát. Dấu tay trên bộ xương tái hiện cảnh bàn tay từ vực ngoại đánh chết sinh linh trong thạch thất rồi bị quy tắc kỳ lạ cắt lìa, qua đó hé lộ nguồn gốc khung xương cánh tay Ninh Xuyên từng lấy được. Khi xác nhận không có khói đen hay khí xám nguy hiểm, Thạch Hạo quay lại hấp thu khí tức Tiên đạo, khiến luồng tiên khí lớn thêm và căn cơ được củng cố. Bên ngoài, Huyết Kích đại diện Thiên quốc đuổi mọi người khỏi hố trời, liên tiếp ám sát những ai không chịu rời đi. Kim văn Bạch Hổ dưới hình dạng mèo bạc xuất hiện, kết minh với Thiên quốc, xé nát một đám người rồi trực tiếp uy hiếp Thạch Hạo phải rời khỏi thạch thất."},{"chuong":883,"tieuDe":"Sóng Gió Lại Nổi","tomTat":"Tại hố trời, một con ngân miêu tự xưng là sủng vật của quái thai cổ đại dùng phù văn âm ba màu bạc đánh trọng thương hàng loạt tu sĩ, buộc mọi người phải rút lui. Huyết Kích, đệ nhị Liệp sát giả của Thiên quốc, thừa cơ ẩn vào hư không tàn sát những người đang tháo chạy nhằm độc chiếm khu vực tiên thể. Dưới lòng đất, Thạch Hạo đang hấp thu khí tức Tiên đạo từ tiên thi khiến tia tiên khí bản thân lớn mạnh thêm, nhưng bị Huyết Kích dùng chiến kích đâm xuống quấy nhiễu. Thạch Hạo lao lên mặt đất, chỉ dùng hai ngón tay kẹp lưỡi kích rồi lần lượt phá hủy toàn bộ thần binh của đối phương, sau đó lôi Huyết Kích ra khỏi hư không và bóp cổ xách lên. Nhận ra Huyết Kích đang trông chờ đệ nhất Liệp sát giả ám sát mình, Thạch Hạo truyền âm khiêu chiến nhưng không ai đáp lời, cuối cùng hắn giết Huyết Kích đến hình thần đều diệt. Xử lý xong đệ nhị Liệp sát giả, Thạch Hạo dùng thần thức khóa chặt con ngân miêu đang định trốn chạy, nhận định sinh linh này thực chất là Kim văn bạch hổ hiếm có đang che giấu chủng tộc và bắt đầu truy hỏi về chủ nhân thật sự của nó."},{"chuong":884,"tieuDe":"Phong Ấn Của Tiên Cổ","tomTat":"Thạch Hạo chân thân cầm kiếm thai truy kích đệ nhất Liệp sát giả Thiên quốc nhưng đối phương dùng Phá Giới phù thoát đi, Thanh Y và Tào Vũ Sinh cảnh báo kẻ này sẽ phục kích về sau. Quay lại hố trời, Thạch Hạo bất chấp lời cảnh cáo về Cổ Thánh tử sắp hoàn thành bước cuối cùng, đánh bại Kim văn Bạch Hổ của Thần miếu — bẻ gãy móng vuốt từng tôi bằng chất lỏng ao Hỗn độn rồi bắt sống làm nguyên liệu. Đả Thần Thạch phát hiện cổ trận quanh tiên thi và dùng nhiều thần liệu bố trí trận pháp di chuyển thi thể khỏi thạch thất. Khi tiên thi được dời, một bình gốm đen rạn nứt lộ ra bên dưới rồi nổ tung phun máu đen và khói đen, buộc cả nhóm tháo chạy hàng vạn dặm. Ánh sáng Tiên đạo từ tiên thi tịnh hóa máu đen nhưng hủy hơn nửa tiên thể; phần còn lại được thu lấy. Trong tro tàn bình gốm, Thỏ nhỏ phát hiện khối xương trán màu xanh tự run rẩy, không thể bị Thiên nhãn nhìn xuyên, trên đó có dấu vết và khí thế cùng hình lá cây vàng của Liễu Thần, khiến Thạch Hạo và Đả Thần Thạch kinh động."},{"chuong":885,"tieuDe":"Di Vật","tomTat":"Trong tro tàn của bình gốm dưới hố trời, nhóm Thạch Hạo phát hiện xương trán xanh của sinh linh vô thượng bị lá vàng và cành liễu xuyên thủng — tất cả mang khí tức Liễu Thần từ hơn một kỷ nguyên trước. Khi xương trán bất ngờ rung chuyển hư không, khí tức Liễu Thần lưu trên cơ thể Thạch Hạo kích hoạt di vật, khiến lá và cành liễu quấn lấy xương trán rồi cùng thiêu hủy thành bột. Thạch Hạo suy xét về quá khứ chiến đấu của Liễu Thần và nhận ra đại chiến kỷ nguyên trước có thể bùng phát trở lại, quyết tâm tiến tới đỉnh cao Thần đạo. Cả nhóm kiểm tra gần nửa bộ tiên thể nhưng xác nhận phù văn Tiên đạo đã tiêu tán, không thể giúp ngưng tụ tiên khí; Thạch Hạo lấy ra hộp máu đoạt từ truyền nhân Tiên điện nhưng tiếp tục từ chối cấy ghép huyết cốt, kiên trì tự tu luồng tiên khí thứ hai. Vì tin Táng giới còn nhiều dấu vết Liễu Thần, cả nhóm chuyển hướng tới Táng thành — một trong bốn cổ địa lớn, nơi tập trung đông đảo người ngoại lai và dân bản địa gồm nhiều chủng tộc cổ. Vừa tới nơi, họ nghe tin Huyết Kích đã chết và đệ nhất Liệp sát giả bị Hoang đuổi chạy; Thanh Y phát hiện người Thần miếu đang tiến đến, còn Thạch Hạo cảm ứng được một cao thủ cực kỳ đáng sợ trong thành."},{"chuong":886,"tieuDe":"Mạch Nước Ngầm Cuộn Trào","tomTat":"Thạch Hạo cảm nhận vài khí tức siêu tuyệt lướt qua thần niệm trong Táng thành, Tào Vũ Sinh phán đoán đó có thể là quái thai cổ đại hoặc dân bản địa cực mạnh. Thanh Y nhận ra người Thần miếu đã rời đi và dự cảm đại chiến sắp nổ ra. Khi nhóm đi qua phố chợ và vùng núi đỏ nhuộm tiên huyết, Tào Vũ Sinh kể về nửa bộ tiên kinh từng được đào thấy dưới lòng đất và cốt thư từng dẫn Thập Quan vương tới cây nhỏ Tiên đạo. Thiên quốc bất ngờ tập kích bằng cốt kiếm Tích Huyết luyện từ nguyên thủy chân cốt Thiên Thần, nhưng nhờ thần giác tiên khí mà Thạch Hạo kịp đưa đồng bạn tránh rồi dùng kiếm thai chống lại; kẻ địch cho cốt kiếm tự nổ san bằng cả phố chợ. Thạch Hạo tuyên bố giết sạch người Thiên quốc trong Tiên cổ, truy sát và chém đầu sáu sát thủ, nhưng đệ nhất Liệp sát giả đã dùng Phá Giới phù đào thoát. Minh tộc nhân cơ hội dùng bí bảo Thiên Thần Bạch Cốt phiên đánh lén nhưng bị Thạch Hạo phá hủy trung tâm đại trận. Long Vũ xuất hiện tự nhận phụng mệnh Quân Đạo mời nhóm Thạch Hạo kết minh, tiết lộ Minh thổ, Thiên quốc và Thần miếu đã liên thủ, và phe mình có Đọa Thần tử đang chuẩn bị bước ra bước cuối cùng — cái tên khiến Thạch Hạo nhớ tới mối nhục hai sư huynh bị đánh đuổi khỏi Đạo tràng Chí Tôn."},{"chuong":887,"tieuDe":"Đọa Thần Tử","tomTat":"Long Vũ đến Táng thành thuyết phục Thạch Hạo kết minh, phân tích rằng các quái thai cổ đại đang liên thủ và quái thai Thiên quốc là mối nguy lớn nhất. Hắn hé lộ nguồn gốc Hắc Ám Thần tử là xác cổ chôn qua năm đời rồi thông linh, đồng thời cho biết Ninh Xuyên đã xuất quan chỉnh hợp nhân mã và người bí ẩn trong Hung sào cũng có đồng minh. Thạch Hạo tạm đồng ý kết minh và đề nghị đánh Thiên quốc cùng Minh thổ, nhưng Long Vũ khuyên chờ thêm lực lượng. Long Vũ đề nghị dùng chí bảo đổi quyền tham khảo nửa bộ tiên thi của Thạch Hạo rồi dùng Phá Giới phù rời Táng giới đi báo tin. Sau khi Long Vũ rời đi, Thạch Hạo nhận định lời đối phương nửa thật nửa giả và tiết lộ mình có cừu oán với Đọa Thần tử — kẻ từng giẫm đạp hai sư huynh của hắn tại Đạo tràng Chí Tôn. Ở một động phủ cổ khác, Quân Đạo quan sát thấy tiên khí của Đọa Thần tử gần thành hình nhưng hắn từng chủ động dừng đột phá vì sợ hiện tượng kỳ lạ. Đọa Thần tử từ chối dựa vào tiên thi, tuyên bố tự tu thành rồi tiếp tục bế quan. Quân Đạo cũng thử vượt cửa ải và sau một ngày tiến thêm trên đại đạo mà không gặp hiện tượng kỳ lạ."},{"chuong":888,"tieuDe":"Hắc Uyên","tomTat":"Thạch Hạo tuyên bố sẽ chờ Đọa Thần tử xuất hiện để thanh toán ân oán cho hai vị sư huynh, sau đó cùng Tào Vũ Sinh và cả nhóm đi tìm cơ duyên trong Táng thành. Tại vùng núi đỏ sậm, một tu sĩ đào được huyết châu rồi lập tức bị giết, nhưng cuộc tranh đoạt trở nên vô nghĩa vì thần tính bên trong đã tiêu tán. Cả nhóm tiến tới Hắc Uyên ở trung tâm Táng thành, một vực sâu đen kịt được coi là nơi đáng sợ nhất Táng giới, nơi thần thức và phi hành đều bị phong tỏa, các chí cường giả từng liên thủ tiến vào cũng không trở về. Cảm nhận được một lời kêu gọi mơ hồ từ dưới vực, Thạch Hạo bỏ lại Đả Thần Thạch và Hoàng điệp, một mình trèo xuống bất chấp sự can ngăn của Thanh Y. Hắn vượt qua ngưỡng an toàn một trăm trượng, chứng kiến một sinh linh rơi xuống vực không thể bay lên, rồi tiếp tục vượt qua những phù văn nguy hiểm trên vách đá để đạt độ sâu hơn một ngàn ba trăm trượng. Tại đó, Thạch Hạo phát hiện hai chiếc lá xanh không nguyên vẹn của Liễu Thần nằm trong khe đá, cùng rãnh xuyên thủng và máu khô cho thấy nơi đây từng xảy ra đại chiến giữa các sinh linh vô thượng. Tuy nhiên, hắn xác nhận lời kêu gọi mình cảm nhận không đến từ Liễu Thần mà từ một nguồn bí ẩn khác còn ẩn sâu hơn nữa dưới vực."},{"chuong":889,"tieuDe":"Tiên Lộ","tomTat":"Thạch Hạo quyết tâm xuống tận đáy vực sâu để truy tìm nguồn triệu gọi bí ẩn, dùng lò luyện đan và bộ giáp trụ rách nát từ bí cảnh Nguyên Thiên để hộ thân. Giáp trụ bất ngờ thức tỉnh và cộng hưởng với dấu tích lôi điện trong vực, giúp hắn vượt qua các đợt xung kích nguy hiểm. Dọc đường hắn phát hiện chiến trường của nhiều cường giả vô thượng Tiên cổ với vảy Côn Bằng vỡ nát, máu tím và chân vũ có thể thuộc Phượng. Ở chín vạn trượng, hắn tìm thấy cành liễu vàng của Liễu Thần đang ghim trấn áp bộ xương khổng lồ trên vách đá suốt vạn cổ, liền rút ra thu vào túi càn khôn. Xuống tới đáy vực mười vạn trượng phủ đầy hài cốt, hắn phát hiện tế đàn cổ bị hư hại nhưng vẫn bảo tồn nhiều dòng bảo huyết Tiên đạo nguyên thủy chưa khô. Tế đàn hiện ra cảnh tượng chín con rồng kéo quan tài đồng phá phong ấn rời đi sau thất bại của kỷ nguyên Tiên cổ, rồi xuất hiện hình bóng chiếc đỉnh ba chân hai tai đẫm máu từ nơi xa cố giáng lâm, kèm theo lời gọi thúc giục Thạch Hạo bước lên tế đàn tham dự đại chiến."},{"chuong":890,"tieuDe":"Di Mê","tomTat":"Tại đáy vực sâu trong cổ thuyền, chiếc đỉnh ba chân hai tai thần bí xuyên thời không hiển hóa trên tế đàn Tiên lộ tàn khuyết và tàn niệm bên trong gọi đích danh Hoang, mời hắn bước vào để tới một chiến trường bao la khác. Thạch Hạo suýt vô thức tiến lên nhưng thần giác cảnh báo hiểm họa giúp hắn kịp lùi lại. Để kiểm chứng, hắn ném hai cây thánh dược vào hai vùng quanh tế đàn: một cây bị thời gian đảo ngược thoái hóa thành hạt rồi nổ tung, cây kia gia tốc toàn bộ vòng đời tạo ra hàng loạt thế hệ mới trước khi tất cả bị chấn động tế đàn xóa sạch. Nhận ra chưa đủ sức chống lại quy tắc thời không nơi đây, Thạch Hạo thề sẽ đăng lâm đỉnh cao thần đạo rồi quay lại tìm hiểu chân tướng. Trước khi rời đi, hắn nhìn thấy dấu ấn quá khứ của một người mờ ảo bước ra từ đỉnh, đi vào thông đạo hư không rồi biến mất. Khi hắn leo lên khỏi vực sâu, phía trên đã tụ tập nhiều sinh linh; một tu sĩ Đọa Thần lĩnh công khai tuyên bố đại nhân nhà mình muốn gặp Hoang, khiến Tào Vũ Sinh biến sắc."},{"chuong":891,"tieuDe":"Cổ Tổ Tế Linh","tomTat":"Một sứ giả tóc tím có sừng của Đọa Thần tử đến gần vực sâu truyền lời thách thức Hoang, nhưng rút đi khi cảm nhận sát khí từ nhóm Thạch Hạo. Thanh Y ngăn Đả Thần Thạch ra tay vì dân bản địa cấm giao chiến gần vực sâu. Sau thời gian dài bị cho là đã chết, Thạch Hạo bay lên từ độ sâu mười vạn trượng trong bộ giáp rách, mang theo nhiều thần liệu và bắt ba kẻ liên quan đến Thiên quốc cùng Minh thổ. Các lão giả bản địa nhận ra khí tức cổ Tổ Tế Linh trên người hắn, coi hắn là khách quý, đá các tù binh xuống vực và đổi nhiều thánh dược lấy thần liệu. Thạch Hạo giữ lại cành cây của Liễu Thần, dự định tiếp tục thu thập vật kéo dài tính mạng rồi bế quan tu ra luồng tiên khí thứ hai. Trước phòng đấu giá lớn nhất Táng thành, hắn chạm mặt Đọa Thần tử, người đã tu thành tiên khí, và các lão giả bản địa tiến lên cảnh cáo đối phương."},{"chuong":892,"tieuDe":"Phòng Đấu Giá Dị Tộc","tomTat":"Đọa Thần tử tiếp tục khiêu khích Thạch Hạo dù dè chừng các lão giả bản địa, còn Thạch Hạo từ chối để họ thay mình báo thù vì muốn tự tay rửa nhục cho hai sư huynh của Đạo tràng Chí Tôn. Tin hai quái thai sắp quyết chiến khiến đông đảo tu sĩ kéo tới Táng thành, nhưng cả hai tạm hoãn giao chiến để tham dự buổi đấu giá. Thạch Hạo muốn tìm tài nguyên chuẩn bị bế quan tu luồng tiên khí thứ hai, trong khi Đọa Thần tử cũng tới tìm thần trân và liên tục dùng lời nói quấy nhiễu đối thủ. Thanh Y nhìn thấu thủ đoạn tâm chiến ấy, còn Đả Thần Thạch, Thái Âm Ngọc Thỏ và Tào Vũ Sinh đều tỏ rõ bất mãn. Trong đại điện có pháp tắc không gian, Lam Cốt đao được một cô gái thần bí đấu thành công, sau đó nguyên thủy chân cốt Thiên Thần và bức tranh xương ghi khu vực Thiên Thần quả lần lượt xuất hiện. Thạch Hạo không tranh Thiên Thần quả vì muốn tự mình tu tới cảnh giới tương ứng, còn Đọa Thần tử dùng vật liệu quý để tranh bức tranh xương. Khi buổi đấu giá sắp kết thúc, Đọa Thần tử tuyên bố sẽ thu cả nhóm Thạch Hạo làm đầy tớ, khiến cuộc quyết chiến tiến sát thời điểm bùng nổ."},{"chuong":893,"tieuDe":"Tranh Đấu Kịch Liệt","tomTat":"Đọa Thần tử dùng uy thế ép những người khác nhường cốt đồ chỉ đường tới cổ thụ Thiên Thần, đồng thời coi tài sản của nhóm Thạch Hạo là chiến lợi phẩm. Phòng đấu giá tiếp tục công bố bí đồ động phủ Tiên gia, tiết lộ manh mối về cây nhỏ Tiên đạo của Thập Quan vương, nhưng không ai đủ sức trả giá nên bí đồ được giữ lại. Thạch Hạo đấu mua bán thần quả để chuẩn bị cho bước đột phá quan trọng, rồi trao cành liễu của Liễu Thần để đổi lấy Dòng suối sinh mệnh và Phục Sinh thảo. Các ông lão dân bản địa giải thích họ muốn đưa cành liễu về thánh địa để hợp nhất với cành liễu vàng còn sinh cơ của cổ tổ Tế linh. Sau khi Đọa Thần tử nhục mạ hai sư huynh cùng mạch Chí tôn, Thạch Hạo dẫn hắn tới chiến trường cổ ngoài Táng thành để quyết chiến. Đọa Thần tử bộc lộ một luồng tiên khí nhưng bị cú đá của Thạch Hạo đánh bật cánh tay rồi đá trúng mặt, khiến hắn chảy máu và văng ngược ra sau."},{"chuong":894,"tieuDe":"Đối Đầu Quyết Liệt","tomTat":"Thạch Hạo mở đầu trận chiến bằng một cước đánh trúng mặt Đọa Thần tử, khiến vị Vương cổ đại vừa xuất quan chịu nhục trước những người quan chiến. Hai người nhanh chóng chuyển sang giao phong trực diện, quyền và pháp ấn va chạm hàng trăm nghìn lần, làm hư không rạn nứt và dư âm lan rộng. Đọa Thần tử dùng bí bảo phong tỏa không gian để dò hỏi, rồi nhận ra Thạch Hạo cũng đã tu thành một luồng tiên khí trước mình. Sau khi thu hồi bí bảo, hắn tiếp tục thi triển bảo thuật và dùng Đọa Thần ấn tạo ra dị tượng thần ma đáng sợ. Thạch Hạo phối hợp Luân hồi, ánh sáng Thượng Thương cùng mô hình bảo thuật thiên phú thứ ba để phá tan pháp ấn, đánh Đọa Thần tử trọng thương. Cuối cùng, hắn dùng Súc địa thành thốn áp sát, đánh xuyên lồng ngực rồi nện đối thủ vào núi để trả đũa việc hai sư huynh bị làm nhục."},{"chuong":895,"tieuDe":"Thần Thoại Bất Bại","tomTat":"Thạch Hạo tiếp tục áp đảo Đọa Thần tử, khiến đối thủ phải triệu hồi vòng xoáy hắc ám chứa thần thi và ma hài. Đọa Thần tử triển khai Cặp cánh Quang Ám, còn Thạch Hạo dùng Cánh Côn Bằng cùng Thượng Thương chi thủ, Luân hồi và các thần thông khác để giao chiến dữ dội. Sau hơn hai nghìn chiêu, Thạch Hạo đánh tan thân thể đối thủ, nhưng huyết dịch Đọa Thần tử hóa thành Chân phượng và dùng Đoản kiếm tiên kim đánh lén, khiến hắn gần như bị chém thành hai nửa. Nhờ tiên khí, Thạch Hạo hồi phục, trong khi Đọa Thần tử nhiều lần tái sinh bằng thần thông Chân Hoàng nhưng liên tục bị đánh bại và tiêu hao bản nguyên. Cuối cùng, Thạch Hạo xuyên thủng mi tâm, bắt giữ nguyên thần rồi dùng một quyền đánh tan nó; Tiên kiếm Đại La cũng chặn đoản kiếm kéo các mảnh vỡ nguyên thần bỏ chạy. Trước khi tiêu tan, Đọa Thần tử cùng Thạch Hạo đối thoại về sự khác biệt khi bước vào bước tiến mới, chiếc thuyền cổ màu đen và biến cố không rõ."},{"chuong":896,"tieuDe":"Thu Hoạch Khổng Lồ","tomTat":"Thạch Hạo tiết lộ với Đọa Thần tử rằng hắn từng đặt chân lên thuyền cổ màu đen và tiến tới nơi khởi nguồn của những thứ không rõ, khiến đối phương càng tin thanh kiếm thai trong tay hắn chính là Tiên kiếm Đại La của Ngũ Quan vương. Dù Thạch Hạo đề nghị cùng nghiên cứu Chân Hoàng bất tử thuật để đổi lấy bí mật, Đọa Thần tử vẫn giữ tôn nghiêm của một Vương giả cổ đại, thiêu đốt nguyên thần và lựa chọn tự hủy; cuối cùng bị kiếm thai đánh tan ánh lửa linh hồn. Cái chết của Đọa Thần tử chấn động Tiên cổ, xác lập địa vị vương giả của Hoang, đồng thời khiến Đọa Thần lĩnh và các giáo phái bên ngoài kinh hãi. Sau trận chiến, Thạch Hạo luyện hóa tiên khí của đối phương, khiến luồng tiên khí đầu tiên của mình đạt đến trạng thái viên mãn, rồi thu lấy thi thể Long thú, bảo dược, thánh dược, thần dược không rễ cùng nhiều chiến lợi phẩm quý giá. Hắn còn tìm được cây chủy thủ chứa tiên kim bảy màu, từng chém cơ thể mình thành hai, nhưng khi Tiên kiếm Đại La tự động chém xuống, những luồng thải quang trên chủy thủ bất ngờ ngưng tụ và hướng về phía thanh kiếm, mở ra biến động khó lường."},{"chuong":897,"tieuDe":"Ngựa Không Ngừng Vó","tomTat":"Kiếm thai Đại La thức tỉnh và hấp thu toàn bộ tinh hoa tiên kim bảy màu trong đoản kiếm của Đọa Thần lĩnh, sau đó xuất hiện dấu hiệu tự lột xác. Sau khi Đọa Thần tử tử trận, Thạch Hạo thu được thân thể đầu rồng thân hạc cùng nhiều bảo dược và vật phẩm. Thạch Hạo bắt Long Vũ, ép hắn dẫn đường tới hang cổ của Quân Đạo và biết Đọa Thần tử từng muốn dùng thi thể Tiên giúp Quân Đạo đột phá. Đả Thần Thạch bố trí truyền tống trận, đưa nhóm tới vùng núi cổ; Thạch Hạo phá trận pháp bảo vệ rồi tiến vào hang. Quân Đạo dùng con rối, bảo tháp và trận pháp rút lui để chống đỡ, nhưng bị phá hủy phòng tuyến và bị thương trước khi thoát qua hư không. Nhóm Thạch Hạo cướp sạch kho tàng gồm thánh dược, bán thần quả, cốt thư tiên hiền và bốn thần đan, tạo điều kiện cho hắn bế quan tu ra tia tiên khí thứ hai."},{"chuong":898,"tieuDe":"Đường Của Từng Người","tomTat":"Trong hang cổ, Thỏ nhỏ phát hiện chậu đất tím nhạt là Vạn Vật thổ và được Thạch Hạo tặng cho. Đả Thần Thạch ăn mất Hoàng Văn thạch rồi xác lập con đường tiến hóa bằng cách nuốt các loại thần thạch. Nhóm Thạch Hạo kiểm kê kho tàng của Đế Trùng, Đọa Thần tử và Quân Đạo, dùng các cốt thư cùng cảm ngộ làm tư liệu tu luyện. Thanh Y quyết định ra ngoài giải quyết chủ thân, Tào Vũ Sinh chọn đến Trận giới, còn Đả Thần Thạch tiếp tục lấy đá thành đạo. Thạch Hạo đề nghị mọi người chia thi thể Tiên để nghiên cứu ánh sáng Tiên đạo và tìm hiểu cách tu ra tia tiên khí thứ hai. Cuối cùng, cả nhóm uống thần nhưỡng đến say, trong đó Thỏ nhỏ đánh túy quyền còn Tào Vũ Sinh bố trí sát trận trong lúc ngộ đạo."},{"chuong":899,"tieuDe":"Say","tomTat":"Thanh Y cùng Thạch Hạo uống thần tửu đến say, khiến Thạch Hạo vô thức thân mật với nàng rồi bị phản kích. Thạch Hạo phát hiện vận chuyển Cốt văn có thể làm dịu men rượu và dẫn người uống vào trạng thái cảm ngộ đại đạo, sau đó Thanh Y, Thỏ nhỏ và Tào Vũ Sinh cũng cùng ngộ đạo. Tào Vũ Sinh dùng các mảnh mai rùa diễn quẻ trêu Thanh Y nên bị nàng đánh bay lên núi. Đả Thần Thạch hầm bảo thể đầu rồng thân hạc, Thạch Hạo thêm Kim văn Bạch hổ vào nồi để cả nhóm ăn uống bên hồ. Cuối chương, một chim trắng giống Tuyết Hoàng hóa thành thiếu nữ tóc bạc; Thạch Hạo say rượu kể chuyện từng bắt và cắt lông Ngân Hoàng rồi chọc giận nàng mà không nhận ra thân phận."},{"chuong":900,"tieuDe":"Không Thể Nhịn","tomTat":"Thạch Hạo đang say rượu gặp lại Tuyết Lâm, thiếu nữ tóc bạc từng bị hắn bắt giữ và cắt tỉa lông vũ. Hắn gọi nàng là Bạc, khiến Tuyết Lâm nhớ lại chuyện cũ và lập tức dùng lửa phượng hoàng cùng ngân quang công kích. Thạch Hạo dùng Động thiên duy nhất kết hợp với một tia tiên khí để hóa giải đòn đánh, làm Tuyết Lâm kinh ngạc. Tào Vũ Sinh, Thỏ nhỏ, Thanh Y và Đả Thần Thạch lần lượt xuất hiện, giúp cuộc đối đầu chuyển thành một bữa rượu hòa giải. Trong lúc ăn uống, Tuyết Lâm phát hiện thịt Kim văn Bạch hổ là thánh thú của Thần miếu và cánh vàng trên bàn là của Đọa Thần tử. Thạch Hạo cho biết mình đã tu ra một tia tiên khí, đang chuẩn bị tu tia thứ hai, rồi hỏi Tuyết Lâm về manh mối Cung điện Chí tôn. Cuối cùng, hắn mở đỉnh ngọc chứa một nửa Tiên thể và đề nghị chia cho nàng một phần để đổi lấy thông tin."}];
